window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[234]={"id":"234","numero":234,"titre":"Insuffisance cardiaque de l'adulte","objectifs":[{"id":"234-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les l’épidémiologie Insuffisance cardiaque","contenu":"<p>L'<span class=\"kw-def\">insuffisance cardiaque</span> (IC) touche <span class=\"kw-chiffre\">1 à 2 %</span> de la population générale. Sa <span class=\"kw-def\">prévalence</span> <strong>augmente avec l'âge</strong> (âge moyen <span class=\"kw-chiffre\">70-80 ans</span>), avec une <strong>prédominance masculine</strong>. C'est une maladie <span class=\"kw-alerte\">grave</span> : <span class=\"kw-def\">mortalité</span> de <span class=\"kw-chiffre\">10 % à 1 an</span> et <span class=\"kw-chiffre\">50 % à 5 ans</span>.</p>\n      <p>Les <span class=\"kw-etio\">comorbidités</span> sont liées au vieillissement cardiovasculaire : <span class=\"kw-ci\">insuffisance rénale</span>, <span class=\"kw-def\">syndrome métabolique</span>, <span class=\"kw-def\">diabète de type 2</span>, <span class=\"kw-etio\">obésité</span>, pathologie pulmonaire, syndrome d'apnées du sommeil, anémie.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>IC à FE altérée (« jeunes »)</th><th>IC à FE préservée (« âgés »)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span></td><td><span class=\"kw-chiffre\">&lt; 1 %</span></td><td><span class=\"kw-chiffre\">&gt; 10 %</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Hommes &gt; femmes</td><td>Femmes &gt; hommes</td></tr>\n          <tr><td>Cardiopathie causale</td><td><span class=\"kw-etio\">Ischémique</span> ++</td><td><span class=\"kw-etio\">Hypertensive</span> ++</td></tr>\n          <tr><td>Signes cliniques d'IC</td><td>Typiques</td><td>Atypiques</td></tr>\n          <tr><td>FEVG</td><td>Altérée</td><td>Normale</td></tr>\n          <tr><td><span class=\"kw-def\">Comorbidités</span></td><td>Peu ou pas</td><td>Nombreuses</td></tr>\n          <tr><td>Traitements validés</td><td>Nombreux</td><td>Aucun</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"234-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’insuffisance cardiaque (IC), de l’IC à fraction d’éjection (FE) diminuée ou à FE conservée","contenu":"<p>L'<span class=\"kw-def\">insuffisance cardiaque</span> est un <span class=\"kw-def\">syndrome</span> caractérisé par des <span class=\"kw-clinique\">symptômes</span> (<span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">œdème</span> des chevilles, fatigue), parfois associés à des <span class=\"kw-clinique\">signes cliniques</span> (<span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">crépitants</span>, <span class=\"kw-clinique\">turgescence jugulaire</span>), <strong>causés par une anomalie de structure et/ou de fonction du cœur</strong> entraînant un <span class=\"kw-def\">débit cardiaque insuffisant</span> et/ou des <span class=\"kw-def\">pressions intracardiaques augmentées</span>, à l'effort ou au repos.</p>\n      <p>Sur le plan physiopathologique : incapacité du cœur à délivrer un débit adapté aux besoins de l'organisme et/ou à fonctionner avec des pressions de remplissage normales.</p>\n      <p>La <span class=\"kw-def\">classification</span> repose sur la <span class=\"kw-def\">FEVG</span> (fraction d'éjection ventriculaire gauche), car elle conditionne les possibilités thérapeutiques :</p>\n      <table >\n        <thead><tr><th>Type d'IC</th><th>FEVG</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>IC à FEVG réduite (systolique)</td><td><span class=\"kw-chiffre\">≤ 40 %</span></td><td><span class=\"kw-alerte\">Défaillance</span> de la <strong>contraction</strong> du myocarde</td></tr>\n          <tr><td>IC à FEVG intermédiaire</td><td><span class=\"kw-chiffre\">41-49 %</span></td><td>Caractéristiques des deux autres types</td></tr>\n          <tr><td>IC à FEVG préservée (diastolique)</td><td><span class=\"kw-chiffre\">≥ 50 %</span></td><td><span class=\"kw-alerte\">Défaillance</span> du <strong>remplissage</strong> du VG (relaxation, compliance)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Critères diagnostiques</span> de l'IC à FEVG préservée</strong> : symptômes ± signes congestifs + FEVG <span class=\"kw-chiffre\">≥ 50 %</span> + élévation du <span class=\"kw-bio\">BNP</span>/<span class=\"kw-bio\">NT-proBNP</span> + au moins 1 critère parmi : pressions de remplissage augmentées, HVG, dilatation de l'atrium gauche en <span class=\"kw-imagerie\">échocardiographie</span>.</p>","frequence":1},{"id":"234-3","rang":"A","rubrique":"Définition","titre":"Savoir ce qu’est un œdème aigu pulmonaire (OAP) cardiogénique","contenu":"<p>L'<span class=\"kw-def\">œdème aigu pulmonaire (OAP) cardiogénique</span> est la manifestation <strong>la plus fréquente de l'<span class=\"kw-def\">insuffisance cardiaque aiguë</span></strong>. Il survient lorsque du liquide plasmatique diffuse dans les espaces extravasculaires pulmonaires (interstitium, alvéole).</p>\n      <p>Mécanisme <span class=\"kw-def\">hémodynamique</span>, en chaîne :</p>\n      <ul>\n        <li>L'IC entraîne une augmentation brutale des <span class=\"kw-def\">pressions de remplissage</span> du ventricule gauche.</li>\n        <li>↑ pression dans l'oreillette gauche et les capillaires pulmonaires (<span class=\"kw-chiffre\">PCP normale 7-12 mmHg</span>).</li>\n        <li>Si <span class=\"kw-alerte\">PCP &gt; 25 mmHg</span> (au-delà de la pression oncotique, <span class=\"kw-chiffre\">25 mmHg</span>) → formation d'un <strong>transsudat</strong> dans les alvéoles.</li>\n        <li>Les alvéoles sont « inondées », l'hématose est altérée → <span class=\"kw-clinique\">hypoxémie</span> (<span class=\"kw-def\">shunt vrai fonctionnel</span>).</li>\n        <li>Mécanisme compensatoire : <span class=\"kw-clinique\">hyperventilation</span> → hypocapnie initiale.</li>\n      </ul>\n      <div class=\"callout callout-info\">📌 En cas de résolution rapide, on parle de <strong>sub-<span class=\"kw-clinique\">œdème</span> pulmonaire</strong> : il a la <strong>même valeur sémiologique</strong> que l'<span class=\"kw-def\">OAP</span> et reste une <span class=\"kw-alerte\">urgence</span> (risque d'<span class=\"kw-clinique\">évolution</span> vers la <span class=\"kw-alerte\">détresse respiratoire</span> ou le collapsus).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":1},{"id":"234-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition du choc cardiogénique","contenu":"<p>Le <span class=\"kw-def\">choc cardiogénique</span> est défini par l'<strong>incapacité du cœur à générer un débit sanguin suffisant</strong> pour répondre aux besoins métaboliques des organes périphériques, <span class=\"kw-alerte\">après correction de la précharge</span> (c'est-à-dire <strong>en l'absence d'hypovolémie</strong>). La baisse du débit cardiaque entraîne une <span class=\"kw-clinique\">hypoperfusion</span> et une anoxie tissulaire, induisant une <span class=\"kw-alerte\">défaillance des organes périphériques</span> (rein, foie, cerveau).</p>\n      <p>La 1ʳᵉ cause est l'<span class=\"kw-etio\">infarctus du myocarde</span> (environ <span class=\"kw-chiffre\">80 %</span> des cas).</p>\n      <div class=\"callout callout-danger\">⚠️ Confirmation hémodynamique du caractère cardiogénique (après exclusion d'une hypovolémie) : <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> pendant au moins <span class=\"kw-chiffre\">30 min</span>, index cardiaque <span class=\"kw-chiffre\">&lt; 2,2 L/min/m²</span>, <span class=\"kw-chiffre\">PAPO &gt; 15 mmHg</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":0},{"id":"234-5","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître la physiopathologie de l’IC (gauche et droite)","contenu":"<p>Le <span class=\"kw-def\">débit cardiaque</span> (DC) dépend du volume d'éjection systolique (<span class=\"kw-def\">VES = VTD − VTS</span>) et de la fréquence cardiaque. Le VES dépend de trois paramètres : la <span class=\"kw-def\">précharge</span> (degré de remplissage du VG, ≈ <span class=\"kw-def\">VTD</span>), l'<span class=\"kw-def\">inotropisme</span> (contractilité, sous dépendance β-adrénergique) et la <span class=\"kw-def\">postcharge</span> (forces s'opposant à l'éjection).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/physiopath-cycle-vg.png\" alt=\"Cycle pression-volume du ventricule gauche — remplissage, contraction isovolumique, éjection, relaxation isovolumique\" loading=\"lazy\">\n        <figcaption>Cycle pression-volume du ventricule gauche : le VES correspond à la différence entre <span class=\"kw-def\">VTD</span> (volume télédiastolique, précharge) et <span class=\"kw-def\">VTS</span> (volume télésystolique). Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <p>Deux mécanismes d'IC gauche, selon le paramètre intrinsèque atteint :</p>\n      <table >\n        <thead><tr><th></th><th>Atteinte de l'inotropisme</th><th>Atteinte de la compliance</th></tr></thead>\n        <tbody>\n          <tr><td>Type d'IC</td><td>IC à <span class=\"kw-def\">FEVG altérée</span> (systolique)</td><td>IC à <span class=\"kw-def\">FEVG préservée</span> (diastolique)</td></tr>\n          <tr><td>Causes</td><td><span class=\"kw-etio\">Infarctus</span> ++, <span class=\"kw-etio\">myocardite</span>, atteinte <span class=\"kw-etio\">toxique</span></td><td><span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">RA</span>, CMH, CMR, péricardite <span class=\"kw-clinique\">constrictive</span></td></tr>\n          <tr><td>Géométrie du VG</td><td>Dilatation — hypertrophie <strong><span class=\"kw-def\">excentrique</span></strong></td><td>Parois épaissies et fibrosées — hypertrophie <strong><span class=\"kw-def\">concentrique</span></strong></td></tr>\n          <tr><td>Conséquences</td><td>VES ↓ → DC ↓ ; pressions de remplissage ↑ → <span class=\"kw-def\">VTD</span> ↑</td><td>VG rigide : toute ↑ de volume entraîne une ↑ de pression diastolique</td></tr>\n        </tbody>\n      </table>\n      <p>Dans les deux cas, l'<strong>élévation des pressions de remplissage du VG</strong> est à l'origine de l'IC gauche et de l'<span class=\"kw-clinique\">œdème</span> pulmonaire.</p>\n      <p><strong>Remodelage et mécanismes compensateurs</strong> (présents quelle que soit la cause) — bénéfiques à court terme, <span class=\"kw-alerte\">délétères à long terme</span> :</p>\n      <ul>\n        <li><strong>Cardiaques :</strong> ↑ fréquence cardiaque ; dilatation ventriculaire (surcharge de précharge) ; hypertrophie ventriculaire (surcharge de postcharge).</li>\n        <li><strong>Extra-cardiaques (neuro-hormonaux) :</strong> activation du <span class=\"kw-def\">système adrénergique</span> et du <span class=\"kw-def\">SRAA</span> (rétention hydrosodée, vasoconstriction) — ce sont les cibles des traitements de l'IC.</li>\n      </ul>\n      <p><strong>IC droite :</strong> la 1ʳᵉ cause est l'<span class=\"kw-etio\">IC gauche</span> (HTAP post-capillaire) ; viennent ensuite le <span class=\"kw-etio\">cœur pulmonaire</span> (pathologies pulmonaires via l'hypoxémie), l'<span class=\"kw-etio\">IDM</span> du VD et les valvulopathies droites.</p>\n      <div class=\"callout callout-info\">📌 <strong><span class=\"kw-def\">Loi de Laplace</span> :</strong> Contrainte pariétale = (pression × <span class=\"kw-clinique\">diamètre</span> de la cavité) / épaisseur pariétale — explique pourquoi la dilatation aggrave le travail cardiaque.</div>","frequence":1},{"id":"234-6","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître la différence entre OAP cardiogénique et OAP lésionnel","contenu":"<p>Quel que soit le mécanisme, l'<span class=\"kw-def\">OAP</span> correspond à une <span class=\"kw-imagerie\">diffusion</span> de liquide dans les espaces extravasculaires pulmonaires. Deux mécanismes s'opposent :</p>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-def\">OAP</span> cardiogénique (hémodynamique)</th><th><span class=\"kw-def\">OAP</span> lésionnel</th></tr></thead>\n        <tbody>\n          <tr><td>Mécanisme</td><td>↑ <span class=\"kw-def\">pression hydrostatique</span> capillaire (congestion en amont du cœur gauche) ou ↓ pression oncotique</td><td>Altération directe de la <span class=\"kw-def\">membrane alvéolo-capillaire</span> (<span class=\"kw-clinique\">lésion</span> anatomopathologique = <span class=\"kw-def\">SDRA</span>)</td></tr>\n          <tr><td>Pression capillaire pulmonaire</td><td><span class=\"kw-chiffre\">Élevée (&gt; 25 mmHg)</span></td><td><span class=\"kw-chiffre\">Normale ou basse (&lt; 18 mmHg)</span></td></tr>\n          <tr><td>Liquide d'<span class=\"kw-clinique\">œdème</span></td><td><strong><span class=\"kw-def\">Transsudat</span></strong> — pauvre en protides</td><td><strong><span class=\"kw-def\">Exsudat</span></strong> — riche en protides, proche du plasma</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 Les <strong>conséquences pulmonaires sont identiques</strong> quel que soit le mécanisme : <span class=\"kw-def\">shunt vrai fonctionnel</span> (anomalie ventilation/perfusion) et <strong>diminution de la compliance pulmonaire</strong>.</div>","frequence":0},{"id":"234-7","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","contenu":"<p>Devant une <span class=\"kw-clinique\">insuffisance respiratoire aiguë</span>, plusieurs diagnostics différentiels de l'<span class=\"kw-def\">OAP</span> cardiogénique sont à évoquer. L'examen clinique oriente :</p>\n      <table >\n        <thead><tr><th>Pathologie</th><th><span class=\"kw-def\">Terrain</span></th><th>Contexte</th><th>Inspection / auscultation</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">OAP</span> cardiogénique</strong></td><td>Sujet âgé</td><td>Ischémie myocardique, antécédent cardiaque, <span class=\"kw-etio\">HTA</span></td><td><span class=\"kw-clinique\">Expectorations</span> <span class=\"kw-clinique\">mousseuses rose saumoné</span>, <span class=\"kw-clinique\">orthopnée</span> ; <span class=\"kw-clinique\">râles</span> <span class=\"kw-clinique\">crépitants</span> bilatéraux symétriques</td></tr>\n          <tr><td><span class=\"kw-def\">Pneumonie</span></td><td>Jeune ou âgé</td><td><span class=\"kw-clinique\">Fièvre</span>, contexte <span class=\"kw-etio\">infectieux</span></td><td><span class=\"kw-clinique\">Expectorations</span> <span class=\"kw-clinique\">purulentes</span> ; <span class=\"kw-clinique\">crépitants</span> unilatéraux en foyer</td></tr>\n          <tr><td>Exacerbation de <span class=\"kw-def\">BPCO</span></td><td>Sujet âgé</td><td><span class=\"kw-etio\">Tabagisme</span>, bronchite chronique</td><td>Distension thoracique, lèvres pincées ; <span class=\"kw-clinique\">sibilants</span></td></tr>\n          <tr><td>Crise d'<span class=\"kw-def\">asthme</span></td><td>Sujet jeune</td><td>Antécédent asthmatique / <span class=\"kw-etio\">allergique</span></td><td>Freinage expiratoire marqué ; <span class=\"kw-clinique\">sibilants diffus</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres causes d'<span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</strong> à éliminer : <span class=\"kw-alerte\">SDRA</span>, <span class=\"kw-etio\">embolie pulmonaire</span>, <span class=\"kw-alerte\">tamponnade</span>, <span class=\"kw-etio\">épanchement pleural</span> ou <span class=\"kw-etio\">pneumothorax</span>, pneumopathie aiguë, insuffisance respiratoire décompensée.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 235 — Péricardite aiguë · 154 — Infection bronchopulmonaire communautaire</em></p>","frequence":0},{"id":"234-8","rang":"B","rubrique":"Diagnostic positif","titre":"Différencier l’IC à FE diminuée et l’IC à FE conservée","contenu":"<table >\n        <thead><tr><th>Critère</th><th>IC à FE diminuée</th><th>IC à FE conservée</th></tr></thead>\n        <tbody>\n          <tr><td>FEVG</td><td><span class=\"kw-chiffre\">&lt; 40 %</span></td><td><span class=\"kw-chiffre\">≥ 50 %</span></td></tr>\n          <tr><td>Mécanisme</td><td>Défaut de <strong>contraction</strong> (systolique)</td><td>Défaut de <strong>remplissage</strong> (diastolique : relaxation, compliance)</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Plutôt sujet jeune</td><td>Plutôt sujet âgé et femme</td></tr>\n          <tr><td>Cardiopathie causale</td><td><span class=\"kw-etio\">Ischémique</span> ++</td><td><span class=\"kw-etio\">Hypertensive</span> ++, <span class=\"kw-etio\">obésité</span></td></tr>\n          <tr><td>Signes cliniques</td><td>Typiques</td><td>Atypiques</td></tr>\n          <tr><td>Traitement</td><td>Nombreux traitements validés (evidence-based)</td><td>Mal codifié, peu d'études</td></tr>\n        </tbody>\n      </table>\n      <p>Le diagnostic d'<span class=\"kw-def\">IC à FE conservée</span> exige des critères supplémentaires : symptômes ± signes congestifs + FEVG <span class=\"kw-chiffre\">≥ 50 %</span> + élévation du <span class=\"kw-bio\">BNP</span>/<span class=\"kw-bio\">NT-proBNP</span> + au moins 1 critère échographique (pressions de remplissage augmentées, HVG, dilatation de l'atrium gauche).</p>\n      <div class=\"callout callout-info\">📌 Avec la progression, <strong>toutes les cardiopathies peuvent évoluer vers une IC à FEVG réduite</strong>.</div>","frequence":0},{"id":"234-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","contenu":"<p>Le diagnostic d'IC peut être <strong>difficile</strong> : les <span class=\"kw-clinique\">symptômes</span> sont peu spécifiques et les <span class=\"kw-clinique\">signes</span> peu sensibles. La démarche diagnostique est <strong>séquentielle</strong> :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>1. Évaluation clinique</td><td><span class=\"kw-etio\">Facteurs de risque</span> (âge, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-def\">diabète</span>, cardiopathie) ; <span class=\"kw-clinique\">symptômes fonctionnels</span> (<span class=\"kw-clinique\">dyspnée</span>, fatigue, <span class=\"kw-clinique\">œdèmes des membres inférieurs</span>) ; <span class=\"kw-clinique\">signes cliniques</span> (<span class=\"kw-clinique\">turgescence jugulaire</span>, <span class=\"kw-clinique\">crépitants</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hépatomégalie</span>)</td></tr>\n          <tr><td>2. Peptides natriurétiques</td><td>Doser le <span class=\"kw-bio\">BNP</span> / <span class=\"kw-bio\">NT-proBNP</span>. Seuils : <span class=\"kw-chiffre\">BNP &gt; 35 pg/mL</span> ou <span class=\"kw-chiffre\">NT-proBNP &gt; 125 pg/mL</span> → poursuivre les investigations ; valeurs normales → IC peu probable</td></tr>\n          <tr><td>3. <span class=\"kw-imagerie\">Échocardiographie</span> (<span class=\"kw-imagerie\">ETT</span>)</td><td>Examen de <strong>référence</strong> pour confirmer ou infirmer : FEVG, dilatation ventriculaire, troubles de relaxation, valvulopathies, pressions de remplissage</td></tr>\n          <tr><td>4. Conclusion</td><td>IC <strong>confirmée</strong> si anomalies à l'<span class=\"kw-imagerie\">ETT</span> (FE réduite, anomalies structurelles) ; IC <strong>exclue</strong> si <span class=\"kw-imagerie\">ETT</span> normale → rechercher une autre cause aux symptômes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 L'apparition des symptômes peut être précédée d'une longue période de <span class=\"kw-def\">dysfonction cardiaque asymptomatique</span>, dont le <span class=\"kw-def\">dépistage</span> permet d'instaurer un traitement et d'améliorer le <span class=\"kw-def\">pronostic</span>.</div>","frequence":3},{"id":"234-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens dans le bilan d’une insuffisance cardiaque","contenu":"<p>Le bilan d'une IC associe des examens de 1ʳᵉ ligne (systématiques) et des examens de 2ᵉ ligne (orientation étiologique).</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ECG</span></td><td>Rarement normal ; oriente l'étiologie (BBG, onde Q de <span class=\"kw-clinique\">nécrose</span>, HVG) ; dépiste les troubles du rythme (<span class=\"kw-etio\">FA</span> ++)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Radiographie thoracique</span></td><td>Cardiomégalie (<span class=\"kw-chiffre\">RCT &gt; 0,5</span>) ; retentissement pleuropulmonaire. Son absence n'élimine pas le diagnostic</td></tr>\n          <tr><td><span class=\"kw-bio\">BNP / NT-proBNP</span></td><td>Bonne valeur prédictive négative ; recommandés pour le diagnostic</td></tr>\n          <tr><td><span class=\"kw-imagerie\">ETT</span></td><td>Examen clé du <span class=\"kw-def\">diagnostic positif</span> et étiologique</td></tr>\n          <tr><td><span class=\"kw-bio\">Biologie</span></td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">HbA1c</span>, <span class=\"kw-bio\">bilan lipidique</span> ; TSHus ; bilan du fer (carence martiale, hémochromatose)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Examens de 2ᵉ intention</strong> (selon le contexte étiologique) : coroscanner, <span class=\"kw-imagerie\">coronarographie</span>, <span class=\"kw-imagerie\">IRM cardiaque</span>, <span class=\"kw-imagerie\">scintigraphie</span> isotopique, cathétérisme droit, <span class=\"kw-imagerie\">Holter</span>-<span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">MAPA</span>, <span class=\"kw-bio\">EFR</span>, test de marche de <span class=\"kw-chiffre\">6 min</span>, <span class=\"kw-imagerie\">épreuve d'effort</span> avec mesure de la <span class=\"kw-bio\">VO₂</span>.</p>","frequence":2},{"id":"234-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","contenu":"<p>Devant un <span class=\"kw-def\">OAP</span> cardiogénique, le bilan en <span class=\"kw-alerte\">urgence</span> vise à confirmer le diagnostic, apprécier la gravité et orienter l'étiologie.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Bilan biologique standard</span></td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme sanguin</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">TP</span>/<span class=\"kw-bio\">TCA</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">ECG · RXT · ETT</span></td><td><span class=\"kw-bio\">ECG</span> (ischémie, trouble du rythme) ; <span class=\"kw-imagerie\">RXT</span> (signes d'<span class=\"kw-def\">OAP</span>) ; <span class=\"kw-imagerie\">ETT</span> (FEVG, étiologie)</td></tr>\n          <tr><td><span class=\"kw-bio\">Troponines</span></td><td>Une élévation modérée est possible même sans pathologie coronarienne aiguë</td></tr>\n          <tr><td><span class=\"kw-bio\">BNP / NT-proBNP</span></td><td>Des valeurs basses (<span class=\"kw-chiffre\">BNP &lt; 100 pg/mL</span> ou <span class=\"kw-chiffre\">NT-proBNP &lt; 125 pg/mL</span>) remettent en cause l'origine cardiaque</td></tr>\n          <tr><td><span class=\"kw-bio\">Gaz du sang artériel</span></td><td>Effet shunt : hypoxie / hypocapnie ; hypercapnie en cas d'épuisement respiratoire ; acidose métabolique si <span class=\"kw-alerte\">état de choc</span> associé</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"234-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt et les limites du BNP ou du NT proBNP pour le diagnostic et le suivi","contenu":"<p>Le <span class=\"kw-bio\">BNP</span> et le <span class=\"kw-bio\">NT-proBNP</span> sont synthétisés et libérés dans la circulation par les <strong>cardiomyocytes étirés</strong> (lors de l'augmentation des pressions intracavitaires). Ils ont une <strong>bonne valeur prédictive négative</strong> : leur principal intérêt est d'<strong>éliminer</strong> le diagnostic d'IC.</p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Seuil rendant l'IC peu probable</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Dyspnée</span> aiguë</td><td><span class=\"kw-chiffre\">BNP &lt; 100 pg/mL</span> ou <span class=\"kw-chiffre\">NT-proBNP &lt; 300 pg/mL</span></td></tr>\n          <tr><td>Présentation chronique</td><td><span class=\"kw-chiffre\">BNP &lt; 35 pg/mL</span> ou <span class=\"kw-chiffre\">NT-proBNP &lt; 125 pg/mL</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Seuils NT-proBNP en fonction de l'âge (LiSA — dyspnée aiguë)</strong> : <span class=\"kw-chiffre\">&gt; 450 pg/mL avant 50 ans</span>, <span class=\"kw-chiffre\">&gt; 900 pg/mL entre 50 et 75 ans</span>, <span class=\"kw-chiffre\">&gt; 1 800 pg/mL après 75 ans</span> → IC très probable. Un <span class=\"kw-chiffre\">NT-proBNP &lt; 300 pg/mL</span> exclut l'IC aiguë quel que soit l'âge.</p>\n      <p><strong>Facteurs influençant les valeurs :</strong> les <strong>augmentent</strong> — âge, sexe féminin, <span class=\"kw-ci\">insuffisance rénale</span>, <span class=\"kw-etio\">fibrillation atriale</span> ; les <strong>diminuent</strong> — <span class=\"kw-etio\">obésité</span>.</p>\n      <div class=\"callout callout-info\">⚠️ Sous <span class=\"kw-ttt\">ARNI</span> (sacubitril-valsartan) : le <span class=\"kw-bio\">BNP</span> augmente et devient <span class=\"kw-alerte\">ininterprétable</span> (il est substrat de la <span class=\"kw-def\">néprilysine</span>). Le <span class=\"kw-bio\">NT-proBNP</span> n'étant <strong>pas</strong> substrat de la <span class=\"kw-def\">néprilysine</span>, sa concentration reste interprétable.</div>","frequence":0},{"id":"234-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la valeur de l’échocardiographie transthoracique dans le diagnostic positif et étiologique","contenu":"<p>L'<span class=\"kw-imagerie\">échocardiographie-doppler transthoracique (ETT)</span> est l'<strong>examen clé</strong> du <span class=\"kw-def\">diagnostic positif</span> <strong>et</strong> étiologique de l'IC ; elle est aussi utile pour ajuster le traitement. Elle est indiquée si <span class=\"kw-chiffre\">BNP &gt; 35 pg/mL</span> ou <span class=\"kw-chiffre\">NT-proBNP &gt; 125 pg/mL</span>, ou si l'IC est fortement suspectée.</p>\n      <p><strong>Renseignements apportés :</strong></p>\n      <ul>\n        <li>Taille du VG : diamètres (<span class=\"kw-def\">DDVG</span>, <span class=\"kw-def\">DSVG</span>) ou volumes (<span class=\"kw-def\">VTD</span>, <span class=\"kw-def\">VTS</span>).</li>\n        <li><span class=\"kw-def\">FEVG</span> — valeurs normales <span class=\"kw-chiffre\">&gt; 50-60 %</span>.</li>\n        <li>Taille et fonction du VD, taille de la veine cave inférieure, taille des atriums.</li>\n        <li>Aspect des valves ; niveau des pressions de remplissage (flux <span class=\"kw-imagerie\">doppler</span>).</li>\n        <li>Indices hémodynamiques : débit cardiaque, pressions pulmonaires ; diamètres de l'aorte thoracique.</li>\n        <li>Évaluation du <strong>péricarde</strong> (épanchement, constriction).</li>\n      </ul>","frequence":2},{"id":"234-14","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","contenu":"<p>La <span class=\"kw-imagerie\">radiographie thoracique</span> d'un <span class=\"kw-def\">OAP</span> d'origine hémodynamique évolue en <strong>3 stades</strong> de gravité croissante.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Signes radiographiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Stade</span> 1 — redistribution vasculaire</td><td>Redistribution du flux vers les sommets : <span class=\"kw-radio\">égalisation du calibre</span> des vaisseaux de la base au sommet (évaluable seulement sur cliché debout)</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 2 — <span class=\"kw-clinique\">œdème</span> interstitiel</td><td><span class=\"kw-radio\">Lignes de Kerley B</span> (<span class=\"kw-clinique\">œdème</span> des septums interlobulaires) ; <span class=\"kw-radio\">flou périhilaire</span> ; images réticulo-nodulaires basales ; apparition des scissures ; épanchements pleuraux</td></tr>\n          <tr><td><span class=\"kw-def\">Stade</span> 3 — <span class=\"kw-clinique\">œdème</span> alvéolaire</td><td><span class=\"kw-radio\">Opacités floconneuses</span> confluentes péri-hilaires <span class=\"kw-radio\">« en ailes de papillon »</span>, bilatérales (des formes unilatérales trompeuses existent)</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-radio\">cardiomégalie</span> (rapport cardiothoracique <span class=\"kw-chiffre\">&gt; 0,5</span>) est fréquente, mais son absence n'élimine pas le diagnostic ; son interprétation reste prudente chez un patient alité.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/oap-stade1-schema.png\" alt=\"Schéma du stade 1 radiologique de l'OAP — redistribution vasculaire vers les sommets\" loading=\"lazy\">\n        <figcaption><span class=\"kw-def\">Stade</span> 1 : redistribution vasculaire vers les sommets. Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/oap-stade2-schema.png\" alt=\"Schéma du stade 2 radiologique de l'OAP — œdème interstitiel, lignes de Kerley B\" loading=\"lazy\">\n        <figcaption><span class=\"kw-chiffre\">Stade 2</span> : <span class=\"kw-clinique\">œdème</span> interstitiel (lignes de Kerley B, <span class=\"kw-radio\">flou périhilaire</span>). Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/oap-stade3-schema.png\" alt=\"Schéma du stade 3 radiologique de l'OAP — œdème alvéolaire en ailes de papillon\" loading=\"lazy\">\n        <figcaption><span class=\"kw-chiffre\">Stade 3</span> : <span class=\"kw-clinique\">œdème</span> alvéolaire péri-hilaire « en ailes de papillon ». Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">📌 En cas d'<span class=\"kw-def\">OAP</span> <strong>lésionnel</strong> (<span class=\"kw-alerte\">SDRA</span>), la silhouette cardiaque est généralement <strong>normale</strong> (rapport cardiothoracique normal).</div>","frequence":0},{"id":"234-15","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie thoracique d’un OAP d’origine hémodynamique","contenu":"<p>L'objectif « Contenu multimédia » attend la reconnaissance d'une <span class=\"kw-imagerie\">radiographie thoracique d'OAP d'origine hémodynamique</span> et la description de sa sémiologie.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/234/oap-rxt-annotee-lecture.png\" alt=\"Radiographie thoracique d'un OAP cardiogénique annotée — opacités alvéolaires bilatérales péri-hilaires, lignes de Kerley B, cardiomégalie\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie thoracique</span> d'un <span class=\"kw-def\">OAP</span> d'origine hémodynamique, annotée pour la lecture. Source : fiches sources EDN item 234.</figcaption>\n      </figure>\n      <p><strong>Signes à reconnaître sur le cliché :</strong></p>\n      <ul>\n        <li><span class=\"kw-radio\">Opacités alvéolaires</span> bilatérales, floconneuses, péri-hilaires, « en ailes de papillon ».</li>\n        <li><span class=\"kw-radio\">Redistribution vasculaire</span> vers les sommets.</li>\n        <li><span class=\"kw-radio\">Lignes de Kerley B</span> aux bases (<span class=\"kw-clinique\">œdème</span> interstitiel).</li>\n        <li><span class=\"kw-radio\">Épanchements pleuraux</span> (comblement des culs-de-sac costodiaphragmatiques).</li>\n        <li><span class=\"kw-radio\">Cardiomégalie</span> — rapport cardiothoracique <span class=\"kw-chiffre\">&gt; 0,5</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">📌 La référence est le cliché <strong>postéro-antérieur réalisé debout</strong> : le rapport cardiothoracique et la redistribution vasculaire ne sont pas interprétables sur un cliché au lit en <span class=\"kw-def\">incidence</span> antéropostérieure.</div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/heart-failure-summary","label":"Radiopaedia : Heart failure summary"},{"href":"https://radiopaedia.org/articles/cardiogenic-pulmonary-oedema","label":"Radiopaedia : Cardiogenic pulmonary oedema"},{"href":"https://radiopaedia.org/articles/right-heart-strain","label":"Radiopaedia : Right heart strain"}]},{"id":"234-16","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies de l’IC","contenu":"<p>Toutes les pathologies cardiaques peuvent aboutir à une IC. Les étiologies se classent par <strong>structure atteinte</strong> :</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Coronaires</td><td><span class=\"kw-etio\">Cardiopathie ischémique</span> — <strong>1ʳᵉ cause d'IC à FEVG réduite</strong></td></tr>\n          <tr><td>Vaisseaux</td><td><span class=\"kw-etio\">HTA</span> — augmentation de la postcharge, HVG, altération diastolique</td></tr>\n          <tr><td>Myocarde</td><td>Cardiomyopathies (<span class=\"kw-etio\">CMD</span>, <span class=\"kw-etio\">CMH</span>, <span class=\"kw-etio\">CMR</span>) ; myocardites ; toxiques (<span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">anthracyclines</span>, <span class=\"kw-etio\">trastuzumab</span>) ; cardiomyopathies <span class=\"kw-etio\">infiltratives</span> (<span class=\"kw-etio\">amylose cardiaque</span> — AL / à transthyrétine ATTR, <span class=\"kw-etio\">maladie de Fabry</span>, hémochromatose, sarcoïdose) ; carence en <span class=\"kw-etio\">thiamine (vitamine B1) — béribéri humide</span></td></tr>\n          <tr><td>Valves</td><td>Valvulopathies (RAo, IM, IA, RM) ; <span class=\"kw-etio\">endocardite</span> infectieuse</td></tr>\n          <tr><td>Tissu cardionecteur</td><td>Troubles du rythme (<span class=\"kw-etio\">FA rapide</span> → CMD rythmique), grande <span class=\"kw-clinique\">bradycardie</span>, troubles conductifs</td></tr>\n          <tr><td>Péricarde</td><td><span class=\"kw-etio\">Péricardite constrictive</span>, épanchement abondant, <span class=\"kw-alerte\">tamponnade</span></td></tr>\n          <tr><td>Ventricule droit</td><td>Causes d'IC droite isolée (cœur pulmonaire, <span class=\"kw-etio\">IDM</span> du VD, valvulopathies droites)</td></tr>\n          <tr><td>Débit cardiaque élevé</td><td>Anémie chronique, <span class=\"kw-etio\">hyperthyroïdie</span>, béribéri, maladie de Paget, fistules artério-veineuses</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Amylose cardiaque à transthyrétine (LiSA).</strong> Étiologie sous-diagnostiquée de l'IC à FEVG préservée du sujet âgé. Le diagnostic non invasif repose sur la <span class=\"kw-imagerie\">scintigraphie osseuse aux biphosphonates marqués (⁹⁹ᵐTc-HMDP / DPD / PYP)</span> : une fixation myocardique <strong>Perugini ≥ 2</strong>, associée à l'absence de composant monoclonal (électrophorèse + immunofixation sérique/urinaire + chaînes légères libres), permet de retenir le diagnostic d'ATTR sans biopsie endomyocardique.</div>\n      <p><strong>Respiration périodique de Cheyne-Stokes.</strong> Alternance de cycles d'<span class=\"kw-clinique\">hyperpnée crescendo-decrescendo</span> et d'<span class=\"kw-clinique\">apnées centrales</span> ; observée dans l'IC sévère (bas débit cérébral + hypersensibilité chémoréceptrice), elle est un marqueur de mauvais <span class=\"kw-def\">pronostic</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 233 — Valvulopathie · 224 — <span class=\"kw-etio\">HTA</span> · 232 — <span class=\"kw-def\">Fibrillation atriale</span></em></p>","frequence":1},{"id":"234-17","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les modalités du diagnostic d’un OAP cardiogénique","contenu":"<p>L'<span class=\"kw-def\">OAP</span> cardiogénique réalise un tableau de <strong><span class=\"kw-alerte\">détresse</span> respiratoire de survenue brutale</strong>, souvent nocturne. Il peut être inaugural chez un patient sans cardiopathie connue.</p>\n      <table >\n        <thead><tr><th>Plan</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td>Symptômes</td><td><span class=\"kw-clinique\">Polypnée superficielle</span> ; <span class=\"kw-clinique\">orthopnée</span> (patient assis, jambes pendantes) ; <span class=\"kw-clinique\">toux</span> avec <span class=\"kw-clinique\">expectoration</span> <span class=\"kw-clinique\">mousseuse</span> blanchâtre ou saumonée ; grésillement laryngé ; <span class=\"kw-clinique\">sueurs</span>, angoisse ; <span class=\"kw-clinique\">cyanose</span> ; douleur angineuse possible</td></tr>\n          <tr><td>Signes physiques</td><td><span class=\"kw-clinique\">Tachycardie constante</span> (sauf bradycardisants) ; <span class=\"kw-clinique\">râles crépitants bilatéraux</span> partant des bases vers les sommets (<span class=\"kw-def\">classification</span> de Killip) ; signes d'IC droite associés</td></tr>\n          <tr><td>Pression artérielle</td><td><span class=\"kw-clinique\">HTA réactionnelle</span> fréquente (réaction adrénergique, anxiété) — ne pas attribuer abusivement l'<span class=\"kw-def\">OAP</span> à une crise hypertensive</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-alerte\">Signes de gravité</span></strong> : tableau de <span class=\"kw-alerte\">choc</span> (<span class=\"kw-chiffre\">PAS &lt; 100 mmHg</span>, troubles de la conscience, <span class=\"kw-clinique\">oligurie</span>) ; <span class=\"kw-alerte\">détresse</span> respiratoire (<span class=\"kw-chiffre\">FR &gt; 30</span>, <span class=\"kw-alerte\">tirage</span>, <span class=\"kw-chiffre\">SaO₂ &lt; 90 %</span> sous O₂ à haut débit → impose la <span class=\"kw-ttt\">VNI</span>) ; épuisement respiratoire (<span class=\"kw-clinique\">bradypnée</span>, <span class=\"kw-clinique\">confusion</span>) ; <span class=\"kw-etio\">syndrome coronarien aigu</span> associé.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":1},{"id":"234-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement d’urgence de l’OAP cardiogénique","contenu":"<p>Le traitement de l'<span class=\"kw-def\">OAP</span> cardiogénique vise à <strong>assurer l'oxygénation</strong> et à <strong>réduire la pression hydrostatique capillaire pulmonaire</strong> (baisse de la précharge et de la postcharge). Il doit être démarré sur place, souvent avant les premiers examens complémentaires.</p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Mise en condition</td><td>Position <strong>demi-assise</strong> ; voie veineuse (G5) ; <span class=\"kw-ttt\">oxygénothérapie</span> objectif <span class=\"kw-chiffre\">SaO₂ &gt; 90 %</span> ; monitorage ; <span class=\"kw-ttt\">morphine</span> si anxiété ou <span class=\"kw-clinique\">douleur thoracique</span></td></tr>\n          <tr><td>Ventilation</td><td><span class=\"kw-ttt\">VNI</span> indiquée dans <strong>tous les <span class=\"kw-def\">OAP</span> cardiogéniques</strong> (CPAP ou aide inspiratoire + PEP) ; <span class=\"kw-ttt\">intubation</span> si épuisement respiratoire</td></tr>\n          <tr><td><span class=\"kw-ttt\">Diurétiques</span></td><td><span class=\"kw-ttt\">Diurétique de l'anse</span> — <span class=\"kw-ttt\">furosémide</span> <span class=\"kw-chiffre\">80 mg</span> en IV directe (baisse de la précharge)</td></tr>\n          <tr><td>Dérivés <span class=\"kw-ttt\">nitrés</span></td><td><span class=\"kw-ttt\">Dérivés nitrés</span> IV continu (isosorbide dinitrate, <span class=\"kw-ttt\">trinitrine</span>) : baisse de la pré- et de la postcharge</td></tr>\n          <tr><td>Anticoagulation</td><td><span class=\"kw-ttt\">HBPM</span> à dose préventive, systématique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ Dérivés <span class=\"kw-ttt\">nitrés</span> <span class=\"kw-ci\">contre-indiqués si PAS &lt; 100-110 mmHg</span>. Les <strong>inotropes positifs ne sont PAS indiqués</strong> dans l'<span class=\"kw-def\">OAP</span> cardiogénique (même grave) — ils sont réservés au <span class=\"kw-def\">choc cardiogénique</span>.</div>\n      <div class=\"callout callout-info\">📌 Une amélioration rapide (<span class=\"kw-chiffre\">20-30 min</span>) sous traitement est caractéristique de l'<span class=\"kw-def\">OAP</span> cardiogénique. Effets secondaires à surveiller : <span class=\"kw-clinique\">hypotension</span> (dérivés <span class=\"kw-ttt\">nitrés</span>), hypokaliémie (<span class=\"kw-ttt\">diurétiques</span> de l'anse).</div>","frequence":3},{"id":"234-19","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","contenu":"<p>Les mesures hygiéno-diététiques sont <strong>systématiques chez tous les patients</strong> insuffisants cardiaques.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Recommandations</th></tr></thead>\n        <tbody>\n          <tr><td>Régime hyposodé</td><td>Objectif : ne pas dépasser <span class=\"kw-chiffre\">5-6 g/jour</span> de sel</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span> du poids</td><td>Consulter rapidement si <span class=\"kw-alerte\">prise de poids de 2-3 kg</span>, a fortiori si soudaine (en <span class=\"kw-chiffre\">2-3 jours</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Tabac</span> / <span class=\"kw-etio\">alcool</span></td><td>Arrêt du <span class=\"kw-etio\">tabac</span> impératif ; <span class=\"kw-ttt\">réduction</span> de l'<span class=\"kw-etio\">alcool</span> (surtout dans les CMD)</td></tr>\n          <tr><td>Activité physique</td><td>Activité régulière recommandée — le <span class=\"kw-alerte\">repos strict est délétère</span> (déconditionnement)</td></tr>\n          <tr><td>Vaccinations</td><td>Anti-grippale, anti-pneumococcique, anti-COVID-19</td></tr>\n          <tr><td><span class=\"kw-ci\">Grossesse</span></td><td>À risque (<span class=\"kw-def\">pronostic</span> maternel engagé dans les formes sévères) ; contraception adaptée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong><span class=\"kw-def\">Éducation thérapeutique</span> — 2 mémos :</strong> « <strong><span class=\"kw-def\">EPON</span></strong> » = 4 principes (Exercice physique, se Peser, Observance, Ne pas trop saler) ; « <strong><span class=\"kw-def\">EPOF</span></strong> » = 4 signes d'alerte (Essoufflement, Prise de poids, <span class=\"kw-clinique\">Œdèmes</span>, Fatigue).</div>\n      <p>La <strong><span class=\"kw-ttt\">réadaptation cardiaque</span></strong> associe réentraînement physique, optimisation thérapeutique et <span class=\"kw-def\">éducation thérapeutique</span>. La <strong>télésurveillance</strong> permet de dépister précocement une <span class=\"kw-alerte\">décompensation</span> et d'éviter une <span class=\"kw-alerte\">hospitalisation</span>.</p>","frequence":0},{"id":"234-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","contenu":"<p>Le traitement de l'IC à FEVG diminuée distingue les classes qui <strong>améliorent le <span class=\"kw-def\">pronostic</span></strong> et celles à visée purement <strong>symptomatique</strong>.</p>\n      <table >\n        <thead><tr><th>Effet</th><th>Classes médicamenteuses et dispositifs</th></tr></thead>\n        <tbody>\n          <tr><td>Diminuent la <span class=\"kw-def\">mortalité</span></td><td>\n            <strong><span class=\"kw-ttt\">IEC</span> / <span class=\"kw-ttt\">ARA2</span> :</strong> systématiques quelle que soit la classe NYHA<br>\n            <strong><span class=\"kw-ttt\">Bêtabloquants</span> :</strong> 4 molécules « MéCaBiNé » — <span class=\"kw-ttt\">métoprolol</span> ; <span class=\"kw-ttt\">carvédilol</span> ; <span class=\"kw-ttt\">bisoprolol</span> ; <span class=\"kw-ttt\">nébivolol</span><br>\n            <strong>ARNI :</strong> <span class=\"kw-ttt\">sacubitril-valsartan</span> — en remplacement des <span class=\"kw-ttt\">IEC</span> si patient symptomatique<br>\n            <strong>Antagonistes des minéralocorticoïdes :</strong> <span class=\"kw-ttt\">spironolactone</span> ; <span class=\"kw-ttt\">éplérénone</span><br>\n            <strong>Inhibiteurs de <span class=\"kw-ttt\">SGLT2</span> (gliflozines) :</strong> <span class=\"kw-ttt\">empagliflozine</span> ; <span class=\"kw-ttt\">dapagliflozine</span><br>\n            <strong>Dispositifs :</strong> <span class=\"kw-ttt\">resynchronisation</span> (CRT) ; défibrillateur automatique implantable (DAI)\n          </td></tr>\n          <tr><td>Symptomatiques (pas d'effet démontré sur la <span class=\"kw-def\">mortalité</span>)</td><td><span class=\"kw-ttt\">Diurétiques de l'anse</span> (<span class=\"kw-ttt\">furosémide</span>, <span class=\"kw-ttt\">bumétanide</span>) ; thiazidiques ; <span class=\"kw-ttt\">ivabradine</span> ; dérivés <span class=\"kw-ttt\">nitrés</span> ; <span class=\"kw-ttt\">digoxine</span></td></tr>\n        </tbody>\n      </table>\n      <p>Les <strong><span class=\"kw-ttt\">bêtabloquants</span></strong> sont introduits à <strong>doses très faibles</strong> chez un patient stabilisé, avec augmentation progressive par paliers hebdomadaires.</p>\n      <div class=\"callout callout-info\">⚠️ <strong><span class=\"kw-ci\">Contre-indications</span></strong> dans l'IC à FEVG diminuée : <span class=\"kw-ttt\">inhibiteurs calciques</span> bradycardisants (<span class=\"kw-ci\">diltiazem</span>, <span class=\"kw-ci\">vérapamil</span>) ; antiarythmiques de <span class=\"kw-chiffre\">classe 1</span> (<span class=\"kw-ci\">flécaïnide</span>) ; <span class=\"kw-ci\">AINS</span> (risque de rétention hydrosodée).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":3},{"id":"234-21","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications de l’IC et leur prise en charge","contenu":"<p>L'<span class=\"kw-def\">insuffisance cardiaque</span> est une maladie grave (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">10 % à 1 an</span>, <span class=\"kw-chiffre\">50 % à 5 ans</span>) ; ses complications sont multiples.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr><td>IC chronique réfractaire · <span class=\"kw-clinique\">cachexie</span> cardiaque</td><td><span class=\"kw-def\">Stade</span> avancé ; dénutrition de mauvais <span class=\"kw-def\">pronostic</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Choc cardiogénique</span></td><td><span class=\"kw-clinique\">Hypotension</span>, <span class=\"kw-alerte\">défaillance</span> multiviscérale</td></tr>\n          <tr><td><span class=\"kw-ci\">Insuffisance rénale</span> terminale</td><td><span class=\"kw-def\">Syndrome cardio-rénal</span></td></tr>\n          <tr><td>Troubles hydro-électrolytiques</td><td>Hypo/hyperkaliémie ; <span class=\"kw-bio\">hyponatrémie</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Mort subite</span></td><td>Troubles du rythme ventriculaire (<span class=\"kw-alerte\">TV</span>, FV) — justifie le <span class=\"kw-ttt\">DAI</span></td></tr>\n          <tr><td>Complications thromboemboliques</td><td><span class=\"kw-etio\">AVC</span> (<span class=\"kw-etio\">thrombus</span> des cavités gauches dilatées, FA) ; <span class=\"kw-etio\">embolie pulmonaire</span> (alitement)</td></tr>\n          <tr><td>Autres</td><td>Anémie, carence martiale, syndrome d'apnées du sommeil</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs de mauvais <span class=\"kw-def\">pronostic</span> :</strong> classe <span class=\"kw-chiffre\">NYHA III</span>-IV, réhospitalisations répétées, étiologie <span class=\"kw-etio\">ischémique</span>, FEVG basse, <span class=\"kw-chiffre\">QRS &gt; 120 ms</span> (BBG), <span class=\"kw-bio\">hyponatrémie</span>, <span class=\"kw-bio\">BNP</span> élevé, <span class=\"kw-ci\">insuffisance rénale</span> sévère, <span class=\"kw-bio\">VO₂</span> de pic abaissée.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span> · 232 — <span class=\"kw-def\">Fibrillation atriale</span></em></p>","frequence":1},{"id":"234-22","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les modalités du diagnostic d’un choc cardiogénique","contenu":"<p>Le <span class=\"kw-def\">choc cardiogénique</span> associe un <strong><span class=\"kw-alerte\">état de choc</span></strong> et des signes d'<span class=\"kw-def\">insuffisance cardiaque</span>.</p>\n      <p><strong>Clinique :</strong> <span class=\"kw-clinique\">hypotension</span>, signes d'<span class=\"kw-clinique\">hypoperfusion périphérique</span> (extrémités froides, marbrures), <span class=\"kw-clinique\">oligurie</span>, altération de la conscience, <span class=\"kw-clinique\">sueurs</span> profuses ; les signes d'IC gauche/droite/globale y sont le plus souvent associés.</p>\n      <div class=\"callout callout-info\">⚠️ <strong>Pièges :</strong> les signes d'IC aiguë peuvent être <span class=\"kw-alerte\">frustes</span> (l'hypoperfusion est au premier plan) ; <span class=\"kw-alerte\">30 % des chocs cardiogéniques ont une PA « normale »</span> ; les <span class=\"kw-clinique\">œdèmes des membres inférieurs</span> sont inconstants.</div>\n      <p><strong>Confirmation</strong> (après exclusion d'une hypovolémie) : <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> pendant <span class=\"kw-chiffre\">≥ 30 min</span>, index cardiaque <span class=\"kw-chiffre\">&lt; 2,2 L/min/m²</span>, <span class=\"kw-chiffre\">PAPO &gt; 15 mmHg</span>. Le bilan associe un <span class=\"kw-bio\">ECG</span> 17 dérivations, un bilan <span class=\"kw-ttt\">biologique</span> et l'imagerie ; l'<span class=\"kw-imagerie\">ETT</span> est l'examen clé du <span class=\"kw-def\">diagnostic étiologique</span>.</p>\n      <table >\n        <thead><tr><th>Diagnostic</th><th>Éléments d'orientation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">SCA</span> compliqué de <span class=\"kw-alerte\">choc</span></td><td>FdR cardiovasculaires ; <span class=\"kw-def\">OAP</span> ± souffle nouveau ; <span class=\"kw-imagerie\">sus-décalage du segment ST</span> ; <span class=\"kw-imagerie\">ETT</span> : dysfonction sévère du VG ou complication mécanique</td></tr>\n          <tr><td><span class=\"kw-etio\">Embolie pulmonaire</span></td><td>FdR de thrombose veineuse ; <span class=\"kw-clinique\">turgescence jugulaire</span> sans <span class=\"kw-def\">OAP</span> ; <span class=\"kw-imagerie\">ETT</span> : dilatation des cavités droites, septum paradoxal</td></tr>\n          <tr><td><span class=\"kw-alerte\">Tamponnade</span></td><td>Histoire de péricardite ou de néoplasie ; diminution des bruits du cœur ; <span class=\"kw-imagerie\">ETT</span> : <span class=\"kw-radio\">épanchement péricardique</span> important</td></tr>\n          <tr><td><span class=\"kw-etio\">Pneumothorax</span> compressif</td><td>Homme longiligne ; abolition du murmure vésiculaire et tympanisme</td></tr>\n          <tr><td><span class=\"kw-alerte\"><span class=\"kw-etio\">Dissection</span> aortique</span></td><td><span class=\"kw-etio\">HTA</span> ; <span class=\"kw-clinique\">asymétrie</span> tensionnelle, souffle d'insuffisance aortique ; <span class=\"kw-imagerie\">ETT</span> : flap intimal</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"234-23","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement du choc cardiogénique","contenu":"<p>La prise en charge du <span class=\"kw-def\">choc cardiogénique</span> relève des <strong><span class=\"kw-alerte\">soins intensifs</span> ou de la réanimation</strong>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Mesures générales</td><td>Monitorage invasif de la PA (cathéter artériel) ; sonde urinaire systématique</td></tr>\n          <tr><td>Volémie</td><td>Si hypovolémie : <strong>remplissage prudent par titration</strong> ; si surcharge : <span class=\"kw-ttt\">diurétiques</span></td></tr>\n          <tr><td>Catécholamines</td><td>1ʳᵉ intention : <span class=\"kw-ttt\">dobutamine</span> ; 2ᵉ ligne : ajout de <span class=\"kw-ttt\">noradrénaline</span> ; autres : <span class=\"kw-ttt\">milrinone</span> / <span class=\"kw-ttt\">énoximone</span> (si <span class=\"kw-ttt\">bêtabloquant</span>), <span class=\"kw-ttt\">lévosimendan</span>, <span class=\"kw-ttt\">adrénaline</span></td></tr>\n          <tr><td>Si non-réponse</td><td>Assistance circulatoire (<span class=\"kw-ttt\">ECMO</span>, assistance uni/biventriculaire) ; contre-pulsion intra-aortique ; greffe cardiaque en <span class=\"kw-alerte\">urgence</span></td></tr>\n          <tr><td>Traitement étiologique ++</td><td><span class=\"kw-ttt\">Revascularisation</span> si <span class=\"kw-clinique\">infarctus</span> ; <span class=\"kw-ttt\">drainage</span> si <span class=\"kw-alerte\">tamponnade</span> ; <span class=\"kw-ttt\">thrombolyse</span> si EP grave ; chirurgie si valvulopathie</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">OAP</span> cardiogénique <span class=\"q\">— <span class=\"kw-alerte\">détresse</span> respiratoire brutale</span></strong></p><p>Position <span class=\"kw-ttt\">demi-assise</span> + <span class=\"kw-ttt\">O₂</span> (objectif <span class=\"kw-chiffre\">SaO₂ &gt; 90 %</span>) + <span class=\"kw-ttt\">VNI</span> + <span class=\"kw-ttt\">furosémide IVD</span> + <span class=\"kw-ttt\">dérivés nitrés IV</span></p><ul><li>Traitement à démarrer <span class=\"kw-chiffre\">sur place</span>, souvent avant les premiers examens complémentaires</li><li><span class=\"kw-clinique\">Amélioration rapide</span> (<span class=\"kw-chiffre\">20–30 min</span>) sous traitement = élément caractéristique de l'<span class=\"kw-alerte\">OAP</span> cardiogénique</li></ul><p><strong><span class=\"kw-alerte\">Choc</span> cardiogénique <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale</span></strong></p><p>Transfert en <span class=\"kw-ttt\">soins intensifs / réanimation</span> + <span class=\"kw-ttt\">dobutamine</span> en 1ʳᵉ intention</p><ul><li>1ʳᵉ cause = <span class=\"kw-etio\">infarctus du myocarde</span> (~<span class=\"kw-chiffre\">80 %</span>)</li><li><span class=\"kw-imagerie\">Coronarographie</span> de <span class=\"kw-ttt\">revascularisation</span> <span class=\"kw-alerte\">sans délai</span> si <span class=\"kw-alerte\">SCA</span> — ne pas attendre de « stabiliser » le patient</li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Décompensation</span> d'IC chronique connue :</strong> <span class=\"kw-alerte\">hospitalisation</span> <span class=\"kw-clinique\">fréquente mais non systématique</span> (parfois une simple ↑ des <span class=\"kw-ttt\">diurétiques</span> oraux suffit).<br><strong><span class=\"kw-alerte\">OAP</span> cardiogénique :</strong> PEC initiale possible au domicile / salle classique, puis transfert <span class=\"kw-ttt\">SAU · USIC · réanimation</span>.<br><strong><span class=\"kw-alerte\">Choc</span> cardiogénique :</strong> d'emblée en <span class=\"kw-ttt\">soins intensifs ou réanimation</span>.<br><strong>Appel réanimateur immédiat si :</strong> <span class=\"kw-alerte\">épuisement respiratoire</span>, <span class=\"kw-alerte\">SpO₂ &lt; 92 % sous O₂ ≥ 10 L/min</span>, <span class=\"kw-alerte\">choc</span>, <span class=\"kw-alerte\">hypercapnie</span>, <span class=\"kw-alerte\">hyperlactatémie</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Tableau de choc</span> : <span class=\"kw-chiffre\">PAS &lt; 100 mmHg</span> (anormale dès <span class=\"kw-chiffre\">&lt; 110</span> chez l'hypertendu), troubles de conscience, <span class=\"kw-clinique\">hypoperfusion périphérique</span>, <span class=\"kw-clinique\">oligurie</span></li><li><span class=\"kw-alerte\">Détresse respiratoire</span> : <span class=\"kw-chiffre\">FR &gt; 30</span>, <span class=\"kw-alerte\">tirage</span>, <span class=\"kw-chiffre\">SaO₂ &lt; 90 %</span> sous O₂ à haut débit (impose la <span class=\"kw-ttt\">VNI</span>), <span class=\"kw-chiffre\">FC &gt; 150 bpm</span></li><li><span class=\"kw-alerte\">Épuisement respiratoire</span> : <span class=\"kw-clinique\">bradypnée</span> (<span class=\"kw-chiffre\">FR &lt; 12</span>), <span class=\"kw-clinique\">confusion</span>, aggravation de la <span class=\"kw-clinique\">cyanose</span></li><li><span class=\"kw-alerte\">Syndrome coronarien aigu associé</span> : <span class=\"kw-clinique\">douleur thoracique</span>, <span class=\"kw-imagerie\">sus-décalage du segment ST</span></li><li>Piège : <span class=\"kw-alerte\">30 % des chocs cardiogéniques ont une PA « normale »</span> — l'hypoperfusion est au 1ᵉʳ plan</li></ul>","principes":"<p>Deux logiques à distinguer : <strong>traiter l'<span class=\"kw-alerte\">urgence</span></strong> (<span class=\"kw-alerte\">OAP</span> / <span class=\"kw-alerte\">choc</span>) et <strong>instaurer le traitement de fond</strong> de l'IC chronique. Seul le traitement de fond de l'<span class=\"kw-def\">IC à FEVG réduite</span> améliore le <span class=\"kw-alerte\">pronostic</span>.</p><p><strong><span class=\"kw-alerte\">OAP</span> cardiogénique <span class=\"q\">— traitement d'<span class=\"kw-alerte\">urgence</span></span></strong></p><p><span class=\"kw-ci\">Dérivés nitrés CI si PAS &lt; 100–110 mmHg</span> · <span class=\"kw-ci\">inotropes positifs NON indiqués</span> (réservés au <span class=\"kw-alerte\">choc</span>)</p><ul><li>Position <span class=\"kw-ttt\">demi-assise</span>, <span class=\"kw-ttt\">O₂</span> (objectif <span class=\"kw-chiffre\">SaO₂ &gt; 90 %</span>), <span class=\"kw-ttt\">VVP G5</span>, monitorage, <span class=\"kw-ttt\">morphine</span> si anxiété / douleur</li><li><span class=\"kw-ttt\">VNI</span> dans <strong>tous</strong> les <span class=\"kw-alerte\">OAP</span> cardiogéniques (CPAP ou aide inspiratoire + PEP) ; <span class=\"kw-ttt\">intubation</span> si épuisement</li><li><span class=\"kw-ttt\">Furosémide 80 mg IVD</span> (↓ précharge) + <span class=\"kw-ttt\">dérivés nitrés IV</span> continu (↓ pré- et postcharge)</li><li><span class=\"kw-ttt\">HBPM préventive</span> systématique</li></ul><p><strong>IC chronique à FEVG réduite <span class=\"q\">— traitement de fond pronostique</span></strong></p><p>CI : <span class=\"kw-ci\">inhibiteurs calciques bradycardisants</span> (diltiazem, <span class=\"kw-ttt\">vérapamil</span>), <span class=\"kw-ci\">flécaïnide</span>, <span class=\"kw-ci\">AINS</span></p><ul><li>4 piliers ↓ <span class=\"kw-def\">mortalité</span> : <span class=\"kw-ttt\">IEC/ARA2</span> (ou <span class=\"kw-ttt\">ARNI sacubitril-valsartan</span> si symptomatique) + <span class=\"kw-ttt\">bêtabloquant</span> (MéCaBiNé) + <span class=\"kw-ttt\">anti-aldostérone</span> + <span class=\"kw-ttt\">gliflozine</span></li><li>Dispositifs : <span class=\"kw-ttt\">resynchronisation (CRT)</span>, <span class=\"kw-ttt\">défibrillateur implantable (DAI)</span></li><li>Symptomatiques (sans effet démontré sur la <span class=\"kw-def\">mortalité</span>) : <span class=\"kw-ttt\">diurétiques de l'anse</span>, <span class=\"kw-ttt\">ivabradine</span>, <span class=\"kw-ttt\">digoxine</span></li><li><span class=\"kw-ttt\">Bêtabloquant</span> introduit à <span class=\"kw-chiffre\">doses très faibles</span> chez un patient stabilisé, ↑ progressive par paliers</li></ul><p><strong><span class=\"kw-alerte\">Choc</span> cardiogénique <span class=\"q\">— <span class=\"kw-alerte\">soins intensifs</span> / réanimation</span></strong></p><p><span class=\"kw-ttt\">Traitement étiologique</span> ++ : <span class=\"kw-ttt\">revascularisation</span> si <span class=\"kw-clinique\">infarctus</span>, <span class=\"kw-ttt\">drainage</span> si <span class=\"kw-alerte\">tamponnade</span>, <span class=\"kw-ttt\">thrombolyse</span> si EP grave, chirurgie si valvulopathie</p><ul><li>Monitorage <span class=\"kw-ttt\">invasif de la PA</span> + <span class=\"kw-ttt\">sonde urinaire</span> systématique</li><li>Volémie : <span class=\"kw-ttt\">remplissage prudent par titration</span> si hypovolémie · <span class=\"kw-ttt\">diurétiques</span> si surcharge</li><li>Catécholamines : <span class=\"kw-ttt\">dobutamine</span> en 1ʳᵉ intention, ajout de <span class=\"kw-ttt\">noradrénaline</span> en 2ᵉ ligne</li><li>Si non-réponse : <span class=\"kw-ttt\">assistance circulatoire (ECMO)</span>, <span class=\"kw-ttt\">contre-pulsion intra-aortique</span>, <span class=\"kw-ttt\">greffe</span> en <span class=\"kw-alerte\">urgence</span></li></ul><p><strong>Mesures hygiéno-diététiques & éducation <span class=\"q\">— tous les patients</span></strong></p><p>Consulter rapidement si <span class=\"kw-alerte\">prise de poids de 2–3 kg</span>, a fortiori soudaine (en <span class=\"kw-chiffre\">2–3 jours</span>)</p><ul><li>Régime <span class=\"kw-ttt\">hyposodé</span> (<span class=\"kw-chiffre\">≤ 5–6 g/j</span>) ; <span class=\"kw-ttt\">activité physique</span> régulière (<span class=\"kw-alerte\">repos strict délétère</span>)</li><li>Arrêt du <span class=\"kw-etio\">tabac</span>, <span class=\"kw-ttt\">réduction</span> de l'<span class=\"kw-etio\">alcool</span> ; <span class=\"kw-ttt\">vaccinations</span> (<span class=\"kw-etio\">grippe</span>, <span class=\"kw-etio\">pneumocoque</span>, COVID)</li><li><span class=\"kw-def\">ETP</span> — « <span class=\"kw-def\">EPON</span> » (Exercice, se Peser, Observance, Ne pas saler) et « <span class=\"kw-def\">EPOF</span> » (Essoufflement, Prise de poids, <span class=\"kw-clinique\">Œdèmes</span>, Fatigue)</li></ul>","suivi":"<p><strong><span class=\"kw-alerte\">OAP</span> aigu :</strong> surveiller l'<span class=\"kw-clinique\">amélioration</span> (<span class=\"kw-chiffre\">20–30 min</span>) ; effets secondaires à dépister : <span class=\"kw-clinique\">hypotension</span> (dérivés <span class=\"kw-ttt\">nitrés</span>), <span class=\"kw-bio\">hypokaliémie</span> (<span class=\"kw-ttt\">diurétiques</span> de l'anse).<br><strong>IC chronique :</strong> <span class=\"kw-ttt\">télésurveillance</span> (poids, FC, PA) pour dépister une <span class=\"kw-alerte\">décompensation</span> et éviter l'<span class=\"kw-alerte\">hospitalisation</span> ; <span class=\"kw-def\">suivi</span> par le <span class=\"kw-bio\">NT-proBNP</span> (le <span class=\"kw-bio\">BNP</span> devient <span class=\"kw-alerte\">ininterprétable sous ARNI</span>).<br><strong>Complications :</strong> <span class=\"kw-alerte\">mort subite</span> (<span class=\"kw-alerte\">TV</span>/FV → <span class=\"kw-ttt\">DAI</span>), <span class=\"kw-alerte\">choc cardiogénique</span>, <span class=\"kw-etio\">syndrome cardio-rénal</span>, <span class=\"kw-bio\">troubles hydro-électrolytiques</span>, complications <span class=\"kw-etio\">thromboemboliques</span> (<span class=\"kw-alerte\">AVC</span>, EP).<br><strong>Mauvais <span class=\"kw-def\">pronostic</span> :</strong> <span class=\"kw-def\">NYHA III–IV</span>, réhospitalisations, étiologie <span class=\"kw-etio\">ischémique</span>, FEVG basse, <span class=\"kw-chiffre\">QRS &gt; 120 ms</span> (BBG), <span class=\"kw-bio\">hyponatrémie</span>, <span class=\"kw-bio\">BNP</span> élevé, <span class=\"kw-bio\">VO₂</span> de pic abaissée.</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/12.%20Choc%20cardiog%C3%A9nique.pdf","label":"CeMIR — 12. choc cardiogénique"},{"href":"https://www.sfcardio.fr/page/chapitre-18-item-234-insuffisance-cardiaque-de-ladulte","label":"SFC — Chapitre 18 item 234 insuffisance cardiaque de ladulte"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/15.%20Insuffisance%20cardiaque%20et%20oed%C3%A8me%20aigu%20pulmonaire%20cardiog%C3%A9nique.pdf","label":"CeMIR — 15. insuffisance cardiaque et oedème aigu pulmonaire cardiogénique"},{"href":"https://www.rythmopole.paris/la-resynchronisation-cardiaque/","label":"La resynchronisation cardiaque"},{"href":"https://www.youtube.com/watch?v=UbfEmL1td54","label":"Harzer"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"IC décompensée — profil hémodynamique — Congestion au repos ? (orthopnée, turgescence jugulaire, crépitants, œdèmes) · Hypoperfusion ? (marbrures, extrémités froides, oligurie, PA pincée)","detail":"<h4>CAT — IC décompensée : profil hémodynamique — Classer selon la congestion (humide) et l'hypoperfusion (froid) au repos</h4>","branches":[{"to":"q-humide","label":"Congestion présente (humide)","color":"amber"},{"to":"q-sec","label":"Pas de congestion (sec)","color":"green"}]},{"id":"q-humide","kind":"decision","label":"Hypoperfusion au repos ? — Extrémités froides, marbrures, oligurie, obnubilation, intolérance aux IEC/ARA2","branches":[{"to":"t-chaud-humide","label":"Non — perfusion conservée (chaud)","color":"amber"},{"to":"t-froid-humide","label":"Oui — hypoperfusion (froid)","color":"red"}]},{"id":"t-chaud-humide","kind":"terminal","label":"Chaud et humide","color":"amber","detail":"<h4>Profil</h4><ul><li><span class=\"kw-def\">Congestion</span> sans <span class=\"kw-clinique\">hypoperfusion</span> — profil le <strong>plus fréquent</strong> (<span class=\"kw-def\">OAP cardiogénique</span>, <span class=\"kw-alerte\">décompensation</span> congestive)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Diurétique de l'anse IV</span> (<span class=\"kw-ttt\">furosémide</span>) pour la déplétion</li><li><span class=\"kw-ttt\">Dérivés nitrés IV</span> si PA conservée (↓ pré- et postcharge)</li><li><span class=\"kw-ttt\">O₂</span> (objectif <span class=\"kw-chiffre\">SaO₂ &gt; 90 %</span>) ± <span class=\"kw-ttt\">VNI</span> si <span class=\"kw-alerte\">OAP</span></li></ul><h4>Précaution</h4><ul><li><span class=\"kw-ci\">Dérivés nitrés CI si PAS &lt; 100–110 mmHg</span> · <span class=\"kw-ci\">inotropes positifs non indiqués</span> dans l'<span class=\"kw-alerte\">OAP</span></li></ul>"},{"id":"t-froid-humide","kind":"terminal","label":"Froid et humide","color":"red","detail":"<h4>Profil</h4><ul><li><span class=\"kw-def\">Congestion</span> + <span class=\"kw-alerte\">hypoperfusion</span> = profil le <strong>plus grave</strong> (<span class=\"kw-def\">choc cardiogénique</span>)</li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> pendant <span class=\"kw-chiffre\">≥ 30 min</span> · index cardiaque <span class=\"kw-chiffre\">&lt; 2,2 L/min/m²</span> · <span class=\"kw-chiffre\">PAPO &gt; 15 mmHg</span>, après exclusion d'une hypovolémie</li></ul><h4>Conduite</h4><ul><li>Transfert en <span class=\"kw-ttt\">soins intensifs / réanimation</span></li><li><span class=\"kw-ttt\">Dobutamine</span> en 1ʳᵉ intention ± <span class=\"kw-ttt\">noradrénaline</span> en 2ᵉ ligne</li><li><span class=\"kw-ttt\">Diurétiques</span> sur la surcharge ; <span class=\"kw-ttt\">assistance circulatoire (ECMO)</span> si non-réponse</li><li><span class=\"kw-ttt\">Traitement étiologique</span> ++ (<span class=\"kw-ttt\">revascularisation</span> si <span class=\"kw-etio\">infarctus</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 332 (<span class=\"kw-alerte\">état de choc</span>) · Item 339 (<span class=\"kw-alerte\">syndrome coronarien aigu</span>)</li></ul>"},{"id":"q-sec","kind":"decision","label":"Hypoperfusion au repos ? — Extrémités froides, marbrures, oligurie, obnubilation","branches":[{"to":"t-chaud-sec","label":"Non — perfusion conservée (chaud)","color":"green"},{"to":"t-froid-sec","label":"Oui — hypoperfusion (froid)","color":"amber"}]},{"id":"t-chaud-sec","kind":"terminal","label":"Chaud et sec","color":"green","detail":"<h4>Profil</h4><ul><li>Ni <span class=\"kw-def\">congestion</span> ni <span class=\"kw-clinique\">hypoperfusion</span> — patient <strong>compensé</strong> / euvolémique</li></ul><h4>Conduite</h4><ul><li>Optimiser / poursuivre le <span class=\"kw-ttt\">traitement de fond</span> de l'IC à FEVG réduite</li><li>Rechercher et corriger un <span class=\"kw-etio\">facteur déclenchant</span> (écart de régime, <span class=\"kw-etio\">FA rapide</span>, infection, arrêt de traitement)</li><li>Renforcer l'<span class=\"kw-ttt\">éducation thérapeutique</span> et l'observance</li></ul>"},{"id":"t-froid-sec","kind":"terminal","label":"Froid et sec","color":"amber","detail":"<h4>Profil</h4><ul><li><span class=\"kw-clinique\">Hypoperfusion</span> sans <span class=\"kw-def\">congestion</span> — bas débit, parfois <span class=\"kw-etio\">hypovolémie</span> relative (sur-diurèse)</li></ul><h4>Conduite</h4><ul><li>Réévaluer la <span class=\"kw-clinique\">volémie</span> ; <span class=\"kw-ttt\">remplissage prudent par titration</span> si hypovolémie</li><li>Éviter une <span class=\"kw-ci\">déplétion excessive</span> ; alléger les <span class=\"kw-ttt\">diurétiques</span> si besoin</li><li>Avis spécialisé ; discuter un <span class=\"kw-ttt\">inotrope</span> si bas débit persistant</li></ul>"}]},"cards":[{"i":"5a0519765f2d","n":234,"o":"234-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","q":"Quelle est l'utilité des troponines et du BNP/NT-proBNP en urgence face à un OAP cardiogénique ?","a":"<p>L'utilité est la suivante :</p><ul><li>Les <strong>troponines</strong> : Une <strong>élévation modérée</strong> est possible même en l'absence de pathologie coronarienne aiguë, mais une élévation significative doit faire rechercher une ischémie.</li><li>Le <strong>BNP / NT-proBNP</strong> : Des <strong>valeurs basses</strong> (<strong>BNP &lt; 100 pg/mL</strong> ou <strong>NT-proBNP &lt; 125 pg/mL</strong>) permettent de remettre en cause l'origine cardiaque de la dyspnée.</li></ul>"},{"i":"95e4fe0eb8c1","n":234,"o":"234-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","q":"Que révèle l'analyse des gaz du sang artériel en urgence devant un OAP cardiogénique ?","a":"<p>L'analyse des gaz du sang artériel peut révéler :</p><ul><li>Un <strong>effet shunt</strong>, se manifestant par une <strong>hypoxie</strong> et une <strong>hypocapnie</strong> (par hyperventilation compensatrice).</li><li>Une <strong>hypercapnie</strong> si le patient présente un épuisement respiratoire.</li><li>Une <strong>acidose métabolique</strong> si l'OAP est associé à un état de choc.</li></ul>"},{"i":"c8a3e79ff91f","n":234,"o":"234-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","q":"Quand l'ECG, la radiographie thoracique et l'échographie transthoracique sont-ils indiqués en urgence face à un OAP cardiogénique, et que recherchent-ils ?","a":"<p>Ces examens sont indiqués de manière systématique en urgence pour un OAP cardiogénique :</p><ul><li>L'<strong>ECG</strong> recherche une <strong>ischémie myocardique</strong> ou un <strong>trouble du rythme</strong>.</li><li>La <strong>radiographie thoracique</strong> (RXT) met en évidence les <strong>signes d'OAP</strong> (cardiomégalie, redistribution vasculaire, lignes de Kerley, infiltrats interstitiels/alvéolaires).</li><li>L'<strong>échographie transthoracique</strong> (ETT) évalue la <strong>fraction d'éjection du ventricule gauche (FEVG)</strong> et permet d'orienter vers l'<strong>étiologie</strong> de l'OAP.</li></ul>"},{"i":"d24340a3fb65","n":234,"o":"234-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en urgence dans l’OAP cardiogénique","q":"Quels examens biologiques initiaux sont systématiquement demandés en urgence devant un OAP cardiogénique ?","a":"<p>Les examens biologiques initiaux en urgence comprennent :</p><ul><li>Une <strong>NFS</strong> (Numération Formule Sanguine)</li><li>Un <strong>ionogramme sanguin</strong></li><li>L'<strong>urée</strong> et la <strong>créatinine</strong></li><li>Un <strong>bilan hépatique</strong></li><li>Un <strong>TP / TCA</strong> (Temps de Quick / Temps de Céphaline Activée)</li></ul>"},{"i":"366722a0b2c3","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quels signes radiographiques sont observés au stade 3 (œdème alvéolaire) de la radiographie dans un OAP d'origine hémodynamique ?","a":"<p>Le stade 3 d'œdème alvéolaire est caractérisé par des <strong>opacités floconneuses confluentes péri-hilaires</strong>, classiquement décrites « <strong>en ailes de papillon</strong> ». Elles sont généralement bilatérales, bien que des formes unilatérales existent.</p>"},{"i":"3df0600dfe70","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quelle est l'importance de la cardiomégalie à la radiographie thoracique dans le diagnostic d'OAP d'origine hémodynamique ?","a":"<p>La <strong>cardiomégalie</strong> (rapport cardiothoracique supérieur à <strong>0,5</strong>) est fréquente mais <strong>son absence n'élimine pas le diagnostic</strong> d'OAP d'origine hémodynamique. Son interprétation doit être prudente chez un patient alité.</p>"},{"i":"bf4e2d1f701c","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quels signes radiographiques caractérisent le stade 1 de la radiographie dans un OAP d'origine hémodynamique ?","a":"<p>Le stade 1 correspond à une <strong>redistribution vasculaire</strong> avec une <strong>égalisation du calibre des vaisseaux de la base au sommet</strong>, évaluable sur un cliché debout.</p>"},{"i":"e9971787389d","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quels signes radiographiques caractérisent le stade 2 (œdème interstitiel) de la radiographie dans un OAP d'origine hémodynamique ?","a":"<p>Le stade 2 d'œdème interstitiel est caractérisé par :</p><ul><li>Les <strong>lignes de Kerley B</strong> (œdème des septums interlobulaires).</li><li>Un <strong>flou périhilaire</strong>.</li><li>Des images réticulo-nodulaires basales.</li><li>L'apparition des scissures.</li><li>Des <strong>épanchements pleuraux</strong>.</li></ul>"},{"i":"f7785d682533","n":234,"o":"234-14","u":"Examens complémentaires","t":"Connaître la sémiologie radiographique dans un OAP d’origine hémodynamique","q":"Quels sont les stades évolutifs de la radiographie thoracique dans un œdème aigu du poumon (OAP) d'origine hémodynamique ?","a":"<p>La radiographie thoracique d'un OAP d'origine hémodynamique évolue en <strong>3 stades de gravité croissante</strong> :</p><ul><li><strong>Stade 1</strong> : Redistribution vasculaire.</li><li><strong>Stade 2</strong> : Œdème interstitiel.</li><li><strong>Stade 3</strong> : Œdème alvéolaire.</li></ul>"},{"i":"cd686dd0fced","n":234,"o":"234-15","u":"Contenu multimédia","t":"Radiographie thoracique d’un OAP d’origine hémodynamique","q":"Quels sont les signes radiologiques évocateurs d'un œdème aigu du poumon (OAP) d'origine hémodynamique sur une radiographie thoracique ?","a":"<p>Les signes radiologiques sont :</p><ul><li>Des <strong>opacités alvéolaires bilatérales</strong>, d'aspect <strong>floconneux</strong>, prédominant en région <strong>péri-hilaire</strong>, souvent décrites « <strong>en ailes de papillon</strong> ».</li><li>Une <strong>redistribution vasculaire</strong> vers les sommets pulmonaires.</li><li>La présence de <strong>lignes de Kerley B aux bases</strong> (signe d'œdème interstitiel).</li><li>Des <strong>épanchements pleuraux</strong>, se manifestant par un comblement des culs-de-sac costo-diaphragmatiques.</li><li>Une <strong>cardiomégalie</strong>, définie par un rapport cardiothoracique <strong>supérieur à 0,5</strong>.</li></ul>"},{"i":"eb9317a290ad","n":234,"o":"234-15","u":"Contenu multimédia","t":"Radiographie thoracique d’un OAP d’origine hémodynamique","q":"Dans quelles conditions de réalisation une radiographie thoracique permet-elle une interprétation fiable du rapport cardiothoracique et de la redistribution vasculaire pour le diagnostic d'OAP hémodynamique ?","a":"<p>Pour une interprétation fiable, la radiographie thoracique doit être réalisée en position <strong>debout</strong> et en incidence <strong>postéro-antérieure</strong> (PA). Les clichés réalisés au lit en incidence antéro-postérieure (AP) ne permettent pas d'interpréter correctement ces signes.</p>"},{"i":"15e3ef17e63e","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque liées à l'atteinte du myocarde ?","a":"<ul><li>Les <strong>cardiomyopathies</strong> (dilatée, hypertrophique, restrictive).</li><li>Les <strong>myocardites</strong>.</li><li>Les <strong>toxiques</strong> : <strong>alcool</strong>, <strong>anthracyclines</strong>.</li></ul>"},{"i":"3c269ee7e57d","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque liées à l'atteinte des valves cardiaques ?","a":"<ul><li>Les <strong>valvulopathies</strong> : <strong>rétrécissement aortique (RAo)</strong>, <strong>insuffisance mitrale (IM)</strong>, <strong>insuffisance aortique (IA)</strong>, <strong>rétrécissement mitral (RM)</strong>.</li><li>L'<strong>endocardite infectieuse</strong>.</li></ul>"},{"i":"46db8707e522","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque liées à l'atteinte des vaisseaux ?","a":"<p>L'<strong>hypertension artérielle (HTA)</strong> est la principale étiologie de l'insuffisance cardiaque liée à l'atteinte des vaisseaux, entraînant une augmentation de la postcharge, une hypertrophie ventriculaire gauche (HVG) et une altération diastolique.</p>"},{"i":"8ac6e2aea632","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque dues à un cœur pulmonaire ou à des atteintes du ventricule droit ?","a":"<ul><li>Le <strong>cœur pulmonaire</strong>.</li><li>L'<strong>infarctus du myocarde du ventricule droit (IDM du VD)</strong>.</li><li>Les <strong>valvulopathies droites</strong>.</li></ul>"},{"i":"ac111072bce0","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque à débit cardiaque élevé ?","a":"<ul><li>L'<strong>anémie chronique</strong>.</li><li>L'<strong>hyperthyroïdie</strong>.</li><li>Le <strong>béribéri</strong>.</li><li>La <strong>maladie de Paget</strong>.</li><li>Les <strong>fistules artério-veineuses</strong>.</li></ul>"},{"i":"adc46dd3ed9b","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelle est la principale étiologie de l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche (FEVG) réduite ?","a":"<p>La principale étiologie de l'insuffisance cardiaque à FEVG réduite est la <strong>cardiopathie ischémique</strong> (d'origine coronaire).</p>"},{"i":"c4aa3d274472","n":234,"o":"234-16","u":"Etiologies","t":"Connaître les principales étiologies de l’IC","q":"Quelles sont les étiologies de l'insuffisance cardiaque liées à l'atteinte du tissu cardionecteur ?","a":"<ul><li>Les <strong>troubles du rythme cardiaque</strong>, notamment la <strong>fibrillation atriale (FA) rapide</strong> pouvant induire une cardiomyopathie rythmique.</li><li>Les <strong>grandes bradycardies</strong>.</li><li>Les <strong>troubles conductifs</strong>.</li></ul>"},{"i":"682cc62748b9","n":234,"o":"234-17","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un OAP cardiogénique","q":"Quels sont les signes physiques à rechercher à l'examen clinique d'un patient présentant un OAP cardiogénique ?","a":"<ul><li>Une <strong>tachycardie</strong> constante (sauf en cas de traitement bradycardisant).</li><li>Des <strong>râles crépitants bilatéraux</strong>, qui montent des bases vers les sommets pulmonaires (selon la classification de Killip).</li><li>Des <strong>signes d'insuffisance cardiaque droite</strong> associés sont possibles.</li><li>La <strong>pression artérielle</strong> peut être élevée (HTA réactionnelle) en raison de l'activation adrénergique et de l'anxiété. Attention de ne pas attribuer abusivement l'OAP à une crise hypertensive.</li></ul>"},{"i":"80e5aff126bc","n":234,"o":"234-17","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un OAP cardiogénique","q":"Quels sont les principaux symptômes rapportés par le patient en cas d'OAP cardiogénique ?","a":"<ul><li>Une <strong>polypnée superficielle</strong> et une <strong>orthopnée</strong> (le patient s'assoit, jambes pendantes pour respirer).</li><li>Une <strong>toux</strong> avec expectoration <strong>mousseuse blanchâtre ou saumonée</strong>.</li><li>Un <strong>grésillement laryngé</strong>.</li><li>Des <strong>sueurs et une angoisse</strong>.</li><li>Une <strong>cyanose</strong>.</li><li>Une <strong>douleur angineuse</strong> est possible.</li></ul>"},{"i":"b212a745a564","n":234,"o":"234-17","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un OAP cardiogénique","q":"Quelle est la présentation typique d'un OAP cardiogénique, notamment concernant son installation ?","a":"<p>L'OAP cardiogénique se caractérise par un tableau de <strong>détresse respiratoire de survenue brutale</strong>, souvent <strong>nocturne</strong>. Il peut même être inaugural chez un patient sans cardiopathie connue.</p>"},{"i":"c0e9ecf8a0b0","n":234,"o":"234-17","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un OAP cardiogénique","q":"Quels sont les signes de gravité à identifier rapidement en cas d'OAP cardiogénique ?","a":"<ul><li>Un tableau de <strong>choc</strong> : <strong>PAS &lt; 100 mmHg</strong>, <strong>troubles de la conscience</strong>, <strong>oligurie</strong>.</li><li>Une <strong>détresse respiratoire</strong> marquée : <strong>FR &gt; 30</strong>, <strong>tirage</strong>, <strong>SaO₂ &lt; 90 % sous O₂ à haut débit</strong> (ce qui impose la VNI).</li><li>Un <strong>épuisement respiratoire</strong> : <strong>bradypnée</strong>, <strong>confusion</strong>.</li><li>Un <strong>syndrome coronarien aigu</strong> associé.</li></ul>"},{"i":"43dc29e26641","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quelle est une caractéristique de l'amélioration de l'OAP cardiogénique sous traitement et l'un des principaux pièges thérapeutiques ?","a":"<ul><li>Une amélioration <strong>rapide</strong> (20-30 min) sous traitement est caractéristique de l'OAP cardiogénique.</li><li>Les <strong>inotropes positifs</strong> ne sont <strong>PAS indiqués</strong> dans l'OAP cardiogénique (même grave) et sont réservés au <strong>choc cardiogénique</strong>.</li></ul>"},{"i":"6cf37fc4190d","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quelles sont les mesures de mise en condition immédiates pour un OAP cardiogénique ?","a":"<ul><li>Position <strong>demi-assise</strong></li><li>Pose d'une <strong>voie veineuse</strong></li><li><strong>Oxygénothérapie</strong> avec un objectif de SaO₂ > <strong>90 %</strong></li><li><strong>Monitorage</strong> (cardiologique et respiratoire)</li><li>Administration de <strong>morphine</strong> si anxiété ou douleur thoracique</li></ul>"},{"i":"8e82e34b94d3","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quels sont les traitements médicamenteux spécifiques de l'OAP cardiogénique et leurs posologies/modes d'administration ?","a":"<ul><li><strong>Diurétique de l'anse</strong> : <strong>furosémide 80 mg en IV directe</strong> (pour baisser la précharge).</li><li><strong>Dérivés nitrés</strong> : en <strong>IV continu</strong> (isosorbide dinitrate, trinitrine) pour baisser la pré- et la postcharge.</li><li><strong>Anticoagulation</strong> : <strong>HBPM</strong> à dose préventive, <strong>systématique</strong>.</li></ul>"},{"i":"973ece4fac9c","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quel est le rôle de la ventilation dans la prise en charge d'urgence de l'OAP cardiogénique ?","a":"<p>La <strong>Ventilation Non Invasive (VNI)</strong> est indiquée dans tous les OAP cardiogéniques (CPAP ou aide inspiratoire + PEP). Une <strong>intubation</strong> est envisagée en cas d'épuisement respiratoire.</p>"},{"i":"ada98203a46f","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quelle est la stratégie générale du traitement d'urgence de l'OAP cardiogénique et quand doit-il être initié ?","a":"<p>La stratégie vise à assurer l'<strong>oxygénation</strong> et à réduire la <strong>pression hydrostatique capillaire pulmonaire</strong> (baisse de la précharge et de la postcharge). Le traitement doit être démarré <strong>sur place</strong>, souvent avant les premiers examens complémentaires.</p>"},{"i":"cf6ea20d9141","n":234,"o":"234-18","u":"Prise en charge","t":"Connaître le traitement d’urgence de l’OAP cardiogénique","q":"Quand les dérivés nitrés sont-ils contre-indiqués dans l'OAP cardiogénique et quel est l'effet secondaire à surveiller pour le furosémide ?","a":"<ul><li>Les dérivés nitrés sont contre-indiqués si la <strong>PAS est inférieure à 100-110 mmHg</strong>.</li><li>L'effet secondaire à surveiller avec le furosémide est l'<strong>hypokaliémie</strong>.</li></ul>"},{"i":"2148b0200da8","n":234,"o":"234-19","u":"Prise en charge","t":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","q":"Quels sont les principes clés de l'éducation thérapeutique du patient insuffisant cardiaque, comprenant les principes de gestion et les signes d'alerte ?","a":"<p>Les principes clés de l'éducation thérapeutique sont résumés par deux mémos :</p><ul><li><strong>« EPON »</strong> pour les 4 principes de gestion : <strong>E</strong>xercice physique, se <strong>P</strong>eser, <strong>O</strong>bservance thérapeutique, <strong>N</strong>e pas trop saler.</li><li><strong>« EPOF »</strong> pour les 4 signes d'alerte de décompensation : <strong>E</strong>ssoufflement, <strong>P</strong>rise de poids, <strong>Œ</strong>dèmes, <strong>F</strong>atigue.</li></ul>"},{"i":"4648c845d052","n":234,"o":"234-19","u":"Prise en charge","t":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","q":"Quelles sont les autres mesures hygiéno-diététiques essentielles à discuter avec un patient insuffisant cardiaque ?","a":"<p>Les autres mesures hygiéno-diététiques essentielles sont :</p><ul><li>L'<strong>arrêt impératif du tabac</strong> et la <strong>réduction de l'alcool</strong> (surtout dans les cardiomyopathies dilatées).</li><li>Une <strong>activité physique régulière recommandée</strong> (le repos strict est délétère).</li><li>La réalisation des <strong>vaccinations</strong> (anti-grippale, anti-pneumococcique, anti-COVID-19).</li><li>Une contraception adaptée, car la <strong>grossesse est à risque</strong> et le pronostic maternel peut être engagé dans les formes sévères d'insuffisance cardiaque.</li></ul>"},{"i":"82d6944c9ca3","n":234,"o":"234-19","u":"Prise en charge","t":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","q":"Quelles sont les mesures hygiéno-diététiques systématiques recommandées chez un patient insuffisant cardiaque pour la prise de son régime alimentaire et le suivi de son poids ?","a":"<p>Pour un patient insuffisant cardiaque, les mesures hygiéno-diététiques relatives au régime alimentaire et au poids sont :</p><ul><li>Un <strong>régime hyposodé</strong> avec pour objectif de ne pas dépasser <strong>5-6 g/jour de sel</strong>.</li><li>Une <strong>surveillance du poids</strong> avec la consigne de consulter rapidement en cas de prise de poids de <strong>2-3 kg</strong>, à fortiori si elle est soudaine (en <strong>2-3 jours</strong>).</li></ul>"},{"i":"d66a17a58e98","n":234,"o":"234-19","u":"Prise en charge","t":"Connaître les principales mesures hygiéno-diététiques, les principes de l’éducation thérapeutique et la réadaptation cardiaque","q":"En quoi consiste la réadaptation cardiaque et quel rôle joue la télésurveillance dans la prise en charge de l'insuffisance cardiaque ?","a":"<p>La <strong>réadaptation cardiaque</strong> associe le <strong>réentraînement physique</strong>, l'<strong>optimisation thérapeutique</strong> et l'<strong>éducation thérapeutique</strong>. La <strong>télésurveillance</strong> est un outil permettant de <strong>dépister précocement une décompensation</strong> et ainsi d'<strong>éviter une hospitalisation</strong>.</p>"},{"i":"193253a9c840","n":234,"o":"234-2","u":"Définition","t":"Connaître la définition de l’insuffisance cardiaque (IC), de l’IC à fraction d’éjection (FE) diminuée ou à FE conservée","q":"Comment l'insuffisance cardiaque est-elle classée selon la fraction d'éjection du ventricule gauche (FEVG) ?","a":"<ul><li><strong>Insuffisance cardiaque à FEVG réduite (ICFEVr)</strong> : FEVG <strong>≤ 40 %</strong>, due à une défaillance de la contraction du myocarde.</li><li><strong>Insuffisance cardiaque à FEVG intermédiaire (ICFEVi)</strong> : FEVG <strong>entre 41 et 49 %</strong>, avec des caractéristiques des deux autres types.</li><li><strong>Insuffisance cardiaque à FEVG préservée (ICFEVp)</strong> : FEVG <strong>≥ 50 %</strong>, due à une défaillance du remplissage du ventricule gauche (anomalies de relaxation ou de compliance).</li></ul>"},{"i":"26adf34752bb","n":234,"o":"234-2","u":"Définition","t":"Connaître la définition de l’insuffisance cardiaque (IC), de l’IC à fraction d’éjection (FE) diminuée ou à FE conservée","q":"Quels sont les critères diagnostiques spécifiques de l'Insuffisance Cardiaque à FEVG préservée (ICFEVp) ?","a":"<p>Le diagnostic de l'ICFEVp repose sur la présence de :</p><ul><li><strong>Symptômes</strong> et/ou <strong>signes de congestion</strong>.</li><li>Une <strong>FEVG ≥ 50 %</strong>.</li><li>Une <strong>élévation du BNP ou du NT-proBNP</strong>.</li><li>Et au moins un critère parmi : <strong>pressions de remplissage augmentées, hypertrophie ventriculaire gauche (HVG)</strong> ou <strong>dilatation de l'atrium gauche</strong> à l'échocardiographie.</li></ul>"},{"i":"b979a3b8fa2c","n":234,"o":"234-2","u":"Définition","t":"Connaître la définition de l’insuffisance cardiaque (IC), de l’IC à fraction d’éjection (FE) diminuée ou à FE conservée","q":"Quelle est la définition générale de l'insuffisance cardiaque ?","a":"<p>L'insuffisance cardiaque est un <strong>syndrome clinique</strong> caractérisé par des symptômes (<strong>dyspnée, œdème des chevilles, fatigue</strong>) et parfois des signes cliniques (<strong>tachycardie, crépitants, turgescence jugulaire</strong>).</p><p>Ces manifestations sont dues à une <strong>anomalie de structure et/ou de fonction du cœur</strong>, qui entraîne un <strong>débit cardiaque insuffisant</strong> et/ou des <strong>pressions intracardiaques augmentées</strong>, à l'effort ou au repos.</p>"},{"i":"0c08a910cb09","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quelles sont les précautions d'introduction des bêtabloquants dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG) ?","a":"Dans l'IC-FEVG, les bêtabloquants sont introduits à <strong>doses très faibles</strong> chez un patient <strong>stabilisé</strong>, avec une <strong>augmentation progressive</strong> par paliers hebdomadaires."},{"i":"27b7db10ba29","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quels sont les dispositifs médicaux qui améliorent le pronostic dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG) ?","a":"Les dispositifs médicaux qui améliorent le pronostic dans l'IC-FEVG sont la <strong>resynchronisation cardiaque (CRT)</strong> et le <strong>défibrillateur automatique implantable (DAI)</strong>."},{"i":"6373fcab86db","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quelles sont les classes médicamenteuses qui améliorent le pronostic vital dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG) ?","a":"Les classes médicamenteuses qui améliorent le pronostic vital dans l'IC-FEVG sont :\n<ul>\n<li>Les <strong>IEC</strong> (Inhibiteurs de l'Enzyme de Conversion) ou les <strong>ARA2</strong> (Antagonistes des Récepteurs de l'Angiotensine II).</li>\n<li>Les <strong>bêtabloquants</strong> (métoprolol, carvédilol, bisoprolol, nébivolol – « MéCaBiNé »).</li>\n<li>Les <strong>ARNI</strong> (Sacubitril-Valsartan), en remplacement des IEC si le patient reste symptomatique.</li>\n<li>Les <strong>antagonistes des minéralocorticoïdes</strong> (spironolactone, éplérénone).</li>\n<li>Les <strong>inhibiteurs de SGLT2</strong> (gliflozines : empagliflozine, dapagliflozine).</li>\n</ul>"},{"i":"77f20796f1b6","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quelles sont les contre-indications médicamenteuses dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG) ?","a":"Dans l'IC-FEVG, les contre-indications médicamenteuses sont :\n<ul>\n<li>Les <strong>inhibiteurs calciques bradycardisants</strong> (diltiazem, vérapamil).</li>\n<li>Les <strong>antiarythmiques de classe 1</strong> (flécaïnide).</li>\n<li>Les <strong>AINS</strong> (risque de rétention hydrosodée).</li>\n</ul>"},{"i":"9653474a0f67","n":234,"o":"234-20","u":"Prise en charge","t":"Connaître les principales classes médicamenteuses pour le traitement de l’IC à FE diminuée","q":"Quelles sont les classes médicamenteuses à visée purement symptomatique dans l'insuffisance cardiaque à fraction d'éjection ventriculaire gauche diminuée (IC-FEVG), sans effet démontré sur la mortalité ?","a":"Les classes médicamenteuses à visée purement symptomatique dans l'IC-FEVG, n'ayant pas d'effet démontré sur la mortalité, sont :\n<ul>\n<li>Les <strong>diurétiques de l'anse</strong> (furosémide, bumétanide).</li>\n<li>Les <strong>thiazidiques</strong>.</li>\n<li>L'<strong>ivabradine</strong>.</li>\n<li>Les <strong>dérivés nitrés</strong>.</li>\n<li>La <strong>digoxine</strong>.</li>\n</ul>"},{"i":"29e8b82ff412","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Quels sont les signes cliniques clés d'hypoperfusion périphérique et d'insuffisance cardiaque associés à un choc cardiogénique ?","a":"<ul><li><strong>Hypotension</strong></li><li>Signes d'hypoperfusion périphérique : <strong>extrémités froides</strong>, <strong>marbrures</strong></li><li><strong>Oligurie</strong></li><li><strong>Altération de la conscience</strong></li><li><strong>Sueurs profuses</strong></li><li>Signes d'insuffisance cardiaque gauche, droite ou globale, le plus souvent associés.</li></ul>"},{"i":"b273f7925bc2","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Quels sont les trois pièges diagnostiques à connaître concernant les signes cliniques du choc cardiogénique ?","a":"<ul><li>Les signes d'insuffisance cardiaque aiguë peuvent être <strong>frustes</strong> (l'hypoperfusion est alors au premier plan).</li><li>Environ <strong>30%</strong> des chocs cardiogéniques ont une pression artérielle « normale ».</li><li>Les œdèmes des membres inférieurs sont <strong>inconstants</strong>.</li></ul>"},{"i":"d311f16cde17","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Quels sont les examens complémentaires initiaux recommandés pour le diagnostic étiologique du choc cardiogénique ?","a":"<ul><li>Un <strong>ECG 17 dérivations</strong>.</li><li>Un <strong>bilan biologique</strong>.</li><li>L'<strong>imagerie</strong>, avec l'<strong>échographie transthoracique (ETT)</strong> comme examen clé pour le diagnostic étiologique.</li></ul>"},{"i":"f0cc8df15c3f","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Quels sont les critères hémodynamiques permettant de confirmer un choc cardiogénique, une fois une hypovolémie exclue ?","a":"<ul><li>Pression artérielle systolique (PAS) <strong>inférieure à 90 mmHg</strong> pendant <strong>au moins 30 minutes</strong>.</li><li>Index cardiaque <strong>inférieur à 2,2 L/min/m²</strong>.</li><li>Pression artérielle pulmonaire d'occlusion (PAPO) <strong>supérieure à 15 mmHg</strong>.</li></ul>"},{"i":"f66037e5a921","n":234,"o":"234-22","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’un choc cardiogénique","q":"Comment définir le choc cardiogénique, en distinguant ses deux composantes principales ?","a":"<p>Le choc cardiogénique associe un <strong>état de choc</strong> et des <strong>signes d'insuffisance cardiaque</strong>.</p>"},{"i":"2c0136e2822c","n":234,"o":"234-3","u":"Définition","t":"Savoir ce qu’est un œdème aigu pulmonaire (OAP) cardiogénique","q":"Qu'est-ce qu'un œdème aigu pulmonaire (OAP) cardiogénique ?","a":"<p>L'OAP cardiogénique est la <strong>manifestation la plus fréquente de l'insuffisance cardiaque aiguë</strong>. Il se caractérise par la diffusion de <strong>liquide plasmatique dans les espaces extravasculaires pulmonaires</strong> (interstitium et alvéoles), altérant l'hématose et entraînant une <strong>hypoxémie</strong>.</p>"},{"i":"3b6c12821355","n":234,"o":"234-3","u":"Définition","t":"Savoir ce qu’est un œdème aigu pulmonaire (OAP) cardiogénique","q":"Quel est le mécanisme hémodynamique conduisant à l'OAP cardiogénique ?","a":"<p>Un OAP cardiogénique résulte d'une <strong>augmentation brutale des pressions de remplissage du ventricule gauche</strong> due à une insuffisance cardiaque. Cela entraîne une élévation de la pression dans l'oreillette gauche et les capillaires pulmonaires (pression capillaire pulmonaire, PCP). Lorsque la <strong>PCP dépasse 25 mmHg</strong> (la pression oncotique), un transsudat se forme et inonde les alvéoles.</p>"},{"i":"f243dcd3929f","n":234,"o":"234-3","u":"Définition","t":"Savoir ce qu’est un œdème aigu pulmonaire (OAP) cardiogénique","q":"En quoi consiste le sub-œdème pulmonaire et quelle est sa valeur clinique ?","a":"<p>Le <strong>sub-œdème pulmonaire</strong> est une forme d'OAP cardiogénique en <strong>résolution rapide</strong>, mais il a la <strong>même valeur sémiologique</strong> que l'OAP. Il constitue une <strong>urgence</strong> car il présente un risque d'évolution vers une détresse respiratoire ou un collapsus.</p>"},{"i":"4b000a2d6d10","n":234,"o":"234-4","u":"Définition","t":"Connaître la définition du choc cardiogénique","q":"Comment définit-on cliniquement le choc cardiogénique chez l'adulte ?","a":"<p>Le choc cardiogénique est caractérisé par l'<strong>incapacité du cœur à générer un débit sanguin suffisant</strong> pour répondre aux besoins métaboliques des organes périphériques, et ce <strong>après correction de la précharge</strong> (en l'absence d'hypovolémie).</p>"},{"i":"60e9bcde231f","n":234,"o":"234-4","u":"Définition","t":"Connaître la définition du choc cardiogénique","q":"Quels sont les critères hémodynamiques permettant de confirmer le diagnostic de choc cardiogénique, une fois l'hypovolémie exclue ?","a":"<p>Les critères hémodynamiques pour confirmer un choc cardiogénique sont :</p><ul><li>Une Pression Artérielle Systolique (PAS) <strong>inférieure à 90 mmHg</strong> pendant au moins <strong>30 minutes</strong>.</li><li>Un index cardiaque <strong>inférieur à 2,2 L/min/m²</strong>.</li><li>Une Pression Artérielle Pulmonaire d'Occlusion (PAPO) <strong>supérieure à 15 mmHg</strong>.</li></ul>"},{"i":"705f39dc0ed3","n":234,"o":"234-4","u":"Définition","t":"Connaître la définition du choc cardiogénique","q":"Quelle est la principale étiologie du choc cardiogénique chez l'adulte ?","a":"<p>La première cause du choc cardiogénique est l'<strong>infarctus du myocarde</strong>, représentant environ <strong>80 %</strong> des cas.</p>"},{"i":"8e7bd8deef91","n":234,"o":"234-4","u":"Définition","t":"Connaître la définition du choc cardiogénique","q":"Quelles sont les conséquences physiopathologiques principales du choc cardiogénique sur les organes périphériques ?","a":"<p>La baisse du débit cardiaque entraîne :</p><ul><li>Une <strong>hypoperfusion</strong> tissulaire.</li><li>Une <strong>anoxie</strong> tissulaire.</li><li>Des défaillances des <strong>organes périphériques</strong> (rein, foie, cerveau).</li></ul>"},{"i":"7d190aa985c8","n":234,"o":"234-7","u":"Diagnostic positif","t":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","q":"Quels sont les principaux diagnostics différentiels de l'OAP cardiogénique à considérer devant une insuffisance respiratoire aiguë ?","a":"<p>Devant une insuffisance respiratoire aiguë, les principaux diagnostics différentiels de l'OAP cardiogénique à considérer sont :</p><ul><li>la <strong>pneumonie</strong>,</li><li>l'<strong>exacerbation de BPCO</strong>,</li><li>la <strong>crise d'asthme</strong>,</li><li>le <strong>SDRA</strong>,</li><li>l'<strong>embolie pulmonaire</strong>,</li><li>la <strong>tamponnade</strong>,</li><li>l'<strong>épanchement pleural</strong> ou le <strong>pneumothorax</strong>,</li><li>la <strong>pneumopathie aiguë</strong>,</li><li>l'<strong>insuffisance respiratoire décompensée</strong>.</li></ul>"},{"i":"96174d894bc2","n":234,"o":"234-7","u":"Diagnostic positif","t":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","q":"Comment différencier cliniquement une crise d'asthme d'un OAP cardiogénique ?","a":"<p>La différenciation clinique entre une crise d'asthme et un OAP cardiogénique s'appuie sur :</p><ul><li>le <strong>terrain</strong> et le <strong>contexte</strong> : sujet jeune avec antécédent asthmatique ou allergique pour la crise d'asthme, versus sujet âgé avec ischémie myocardique, antécédent cardiaque ou HTA pour l'OAP cardiogénique.</li><li>l'<strong>inspection/auscultation</strong> : freinage expiratoire marqué et <strong>sibilants diffus</strong> pour la crise d'asthme, versus expectorations mousseuses rose saumoné, orthopnée et <strong>râles crépitants bilatéraux symétriques</strong> pour l'OAP cardiogénique.</li></ul>"},{"i":"a863a056e15d","n":234,"o":"234-7","u":"Diagnostic positif","t":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","q":"Comment différencier cliniquement une exacerbation de BPCO d'un OAP cardiogénique ?","a":"<p>La différenciation clinique entre une exacerbation de BPCO et un OAP cardiogénique s'appuie sur :</p><ul><li>le <strong>terrain</strong> et le <strong>contexte</strong> : sujet âgé avec tabagisme et bronchite chronique pour la BPCO, versus sujet âgé avec ischémie myocardique, antécédent cardiaque ou HTA pour l'OAP cardiogénique.</li><li>l'<strong>inspection/auscultation</strong> : distension thoracique, lèvres pincées et <strong>sibilants</strong> pour la BPCO, versus expectorations mousseuses rose saumoné, orthopnée et <strong>râles crépitants bilatéraux symétriques</strong> pour l'OAP cardiogénique.</li></ul>"},{"i":"ff3656e045b5","n":234,"o":"234-7","u":"Diagnostic positif","t":"Savoir argumenter les principaux diagnostics différentiels de l’OAP cardiogénique","q":"Comment différencier cliniquement une pneumonie d'un OAP cardiogénique ?","a":"<p>La différenciation clinique entre une pneumonie et un OAP cardiogénique s'appuie sur :</p><ul><li>le <strong>terrain</strong> : jeune ou âgé pour la pneumonie, versus sujet âgé pour l'OAP cardiogénique.</li><li>le <strong>contexte</strong> : fièvre, contexte infectieux pour la pneumonie, versus ischémie myocardique, antécédent cardiaque ou HTA pour l'OAP cardiogénique.</li><li>l'<strong>inspection/auscultation</strong> : expectorations purulentes et crépitants unilatéraux en foyer pour la pneumonie, versus expectorations mousseuses rose saumoné, orthopnée et râles crépitants bilatéraux symétriques pour l'OAP cardiogénique.</li></ul>"},{"i":"0b0382362529","n":234,"o":"234-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","q":"Quel examen biologique est utilisé en première intention pour orienter le diagnostic d'insuffisance cardiaque, et quels sont les seuils d'alerte ?","a":"<p>L'examen biologique utilisé est le <strong>dosage des peptides natriurétiques BNP ou NT-proBNP</strong>.</p><ul><li>Des valeurs de <strong>BNP > 35 pg/mL</strong> ou <strong>NT-proBNP > 125 pg/mL</strong> doivent faire poursuivre les investigations.</li><li>Des valeurs normales rendent l'insuffisance cardiaque peu probable.</li></ul>"},{"i":"8b6d687044f5","n":234,"o":"234-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","q":"Quelle est la première étape du diagnostic de l'insuffisance cardiaque, et quels éléments cliniques doivent être recherchés ?","a":"<p>La première étape diagnostique de l'insuffisance cardiaque est l'<strong>évaluation clinique</strong>.</p><ul><li>Rechercher les <strong>facteurs de risque</strong> : âge, hypertension artérielle (HTA), diabète, cardiopathie connue.</li><li>Évaluer les <strong>symptômes fonctionnels</strong> : dyspnée, fatigue, œdèmes des membres inférieurs.</li><li>Rechercher les <strong>signes cliniques</strong> : turgescence jugulaire, crépitants pulmonaires, tachycardie, hépatomégalie.</li></ul>"},{"i":"c6b8657867bc","n":234,"o":"234-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","q":"Quel examen paraclinique est l'examen de référence pour confirmer ou infirmer une insuffisance cardiaque ?","a":"<p>L'examen de référence pour confirmer ou infirmer une insuffisance cardiaque est l'<strong>échocardiographie transthoracique (ETT)</strong>.</p><p>Elle permet d'évaluer :</p><ul><li>La <strong>fraction d'éjection ventriculaire gauche (FEVG)</strong>.</li><li>Une éventuelle <strong>dilatation ventriculaire</strong>.</li><li>Des <strong>troubles de relaxation</strong>.</li><li>Des <strong>valvulopathies</strong>.</li><li>Les <strong>pressions de remplissage</strong>.</li></ul>"},{"i":"d9a8a75a199e","n":234,"o":"234-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une insuffisance cardiaque","q":"Dans quelles situations peut-on conclure à une insuffisance cardiaque confirmée ou exclue après la démarche diagnostique séquentielle ?","a":"<ul><li>L'insuffisance cardiaque est <strong>confirmée</strong> si l'échocardiographie transthoracique (ETT) révèle des <strong>anomalies (fraction d'éjection réduite, anomalies structurelles)</strong>.</li><li>L'insuffisance cardiaque est <strong>exclue</strong> si l'ETT est <strong>normale</strong>, il convient alors de rechercher une autre étiologie aux symptômes du patient.</li></ul>"}]};